#include "pcap_archiver.h"

#include <algorithm>
#include <array>
#include <chrono>
#include <cerrno>
#include <cstring>
#include <fcntl.h>
#include <fstream>
#include <iostream>
#include <sstream>
#include <stdexcept>
#include <string_view>
#include <thread>
#include <unistd.h>

namespace pcap_archive {
namespace fs = std::filesystem;

namespace {

template <class T>
void read_number(const json &j, const char *key, T &out) {
	if(j.is_object() && j.contains(key) && j[key].is_number()) {
		out = j[key].get<T>();
	}
}

void read_string(const json &j, const char *key, std::string &out) {
	if(j.is_object() && j.contains(key) && j[key].is_string()) {
		out = j[key].get<std::string>();
	}
}

void read_path(const json &j, const char *key, fs::path &out) {
	std::string value;
	read_string(j, key, value);
	if(!value.empty()) {
		out = value;
	}
}

void read_bool(const json &j, const char *key, bool &out) {
	if(j.is_object() && j.contains(key) && j[key].is_boolean()) {
		out = j[key].get<bool>();
	}
}

std::chrono::system_clock::time_point to_system_time(fs::file_time_type t) {
	return std::chrono::time_point_cast<std::chrono::system_clock::duration>(
	    t - fs::file_time_type::clock::now() + std::chrono::system_clock::now());
}

std::time_t to_time_t(fs::file_time_type t) {
	return std::chrono::system_clock::to_time_t(to_system_time(t));
}

std::string format_time(fs::file_time_type t, const char *fmt) {
	const std::time_t tt = to_time_t(t);
	std::tm tm{};
	localtime_r(&tt, &tm);
	std::array<char, 64> buf{};
	std::strftime(buf.data(), buf.size(), fmt, &tm);
	return std::string(buf.data());
}

bool has_prefix(std::string_view value, std::string_view prefix) {
	return prefix.empty() || (value.size() >= prefix.size() && value.substr(0, prefix.size()) == prefix);
}

bool ends_with(std::string_view value, std::string_view suffix) {
	return value.size() >= suffix.size() && value.substr(value.size() - suffix.size()) == suffix;
}

bool write_all(int fd, const char *data, std::size_t len) {
	while(len > 0) {
		const ssize_t n = ::write(fd, data, len);
		if(n < 0) {
			if(errno == EINTR) {
				continue;
			}
			return false;
		}
		data += n;
		len -= static_cast<std::size_t>(n);
	}
	return true;
}

bool copy_file_fsync(const fs::path &src, const fs::path &dst_tmp) {
	const int in = ::open(src.c_str(), O_RDONLY | O_CLOEXEC);
	if(in < 0) {
		return false;
	}

	const int out = ::open(dst_tmp.c_str(), O_WRONLY | O_CREAT | O_TRUNC | O_CLOEXEC, 0644);
	if(out < 0) {
		::close(in);
		return false;
	}

	bool ok = true;
	std::array<char, 1024 * 1024> buf{};
	for(;;) {
		const ssize_t n = ::read(in, buf.data(), buf.size());
		if(n < 0) {
			if(errno == EINTR) {
				continue;
			}
			ok = false;
			break;
		}
		if(n == 0) {
			break;
		}
		if(!write_all(out, buf.data(), static_cast<std::size_t>(n))) {
			ok = false;
			break;
		}
	}

	if(ok && ::fsync(out) != 0) {
		ok = false;
	}
	if(::close(out) != 0) {
		ok = false;
	}
	::close(in);
	return ok;
}

void fsync_directory(const fs::path &dir) {
	const int fd = ::open(dir.c_str(), O_RDONLY | O_DIRECTORY | O_CLOEXEC);
	if(fd < 0) {
		return;
	}
	::fsync(fd);
	::close(fd);
}

bool same_file_state(const fs::path &path, std::uintmax_t size, fs::file_time_type mtime) {
	std::error_code ec;
	if(!fs::exists(path, ec) || ec) {
		return false;
	}
	const auto current_size = fs::file_size(path, ec);
	if(ec || current_size != size) {
		return false;
	}
	const auto current_mtime = fs::last_write_time(path, ec);
	return !ec && current_mtime == mtime;
}

} // namespace

int load_config_file(const fs::path &path, config &cfg) {
	if(path.empty()) {
		return 0;
	}

	std::ifstream in(path);
	if(!in) {
		std::cerr << "pcap_archiver: failed to open config " << path << std::endl;
		return -1;
	}

	json root;
	try {
		in >> root;
	}
	catch(const std::exception &e) {
		std::cerr << "pcap_archiver: failed to parse config " << path << ": " << e.what() << std::endl;
		return -1;
	}

	const json *j = &root;
	if(root.is_object() && root.contains("pcap_archive") && root["pcap_archive"].is_object()) {
		j = &root["pcap_archive"];
	}
	if(!j->is_object()) {
		std::cerr << "pcap_archiver: config must be an object" << std::endl;
		return -1;
	}

	read_bool(*j, "enabled", cfg.enabled);
	read_path(*j, "source_dir", cfg.source_dir);
	read_string(*j, "source_prefix", cfg.source_prefix);
	read_path(*j, "dest_dir", cfg.dest_dir);
	read_number(*j, "retention_hours", cfg.retention_hours);
	read_number(*j, "retention_seconds", cfg.retention_seconds);
	read_number(*j, "min_free_bytes", cfg.min_free_bytes);
	read_number(*j, "max_used_bytes", cfg.max_used_bytes);
	read_number(*j, "poll_interval_ms", cfg.poll_interval_ms);
	read_bool(*j, "exclude_latest", cfg.exclude_latest);
	read_bool(*j, "append_mtime_suffix", cfg.append_mtime_suffix);

	return 0;
}

archiver::archiver(config cfg)
	: m_cfg(std::move(cfg)) {
}

std::vector<archiver::source_file> archiver::list_source_files() const {
	std::vector<source_file> out;
	std::error_code ec;
	if(!fs::exists(m_cfg.source_dir, ec) || ec) {
		return out;
	}

	for(const auto &entry : fs::directory_iterator(m_cfg.source_dir, ec)) {
		if(ec) {
			break;
		}
		if(!entry.is_regular_file(ec) || ec) {
			ec.clear();
			continue;
		}
		const auto filename = entry.path().filename().string();
		if(!has_prefix(filename, m_cfg.source_prefix)) {
			continue;
		}

		source_file f;
		f.path = entry.path();
		f.size = entry.file_size(ec);
		if(ec) {
			ec.clear();
			continue;
		}
		f.mtime = entry.last_write_time(ec);
		if(ec) {
			ec.clear();
			continue;
		}
		out.push_back(std::move(f));
	}

	std::sort(out.begin(), out.end(), [](const source_file &a, const source_file &b) {
		if(a.mtime != b.mtime) {
			return a.mtime < b.mtime;
		}
		return a.path.filename().string() < b.path.filename().string();
	});

	if(m_cfg.exclude_latest && !out.empty()) {
		out.pop_back();
	}

	return out;
}

std::filesystem::path archiver::destination_path(const source_file &src) const {
	const auto day = format_time(src.mtime, "%Y%m%d");
	const auto hour = format_time(src.mtime, "%H");
	fs::path name = src.path.filename();
	if(m_cfg.append_mtime_suffix) {
		const auto stamp = format_time(src.mtime, "%Y%m%d%H%M%S");
		name = src.path.stem().string() + "_" + stamp + src.path.extension().string();
	}
	return m_cfg.dest_dir / day / hour / name;
}

std::string archiver::copied_key(const source_file &src) const {
	std::ostringstream oss;
	oss << src.path.string() << '|' << src.size << '|' << src.mtime.time_since_epoch().count();
	return oss.str();
}

bool archiver::already_archived(const source_file &src, const fs::path &dst) const {
	const auto key = copied_key(src);
	if(m_copied_keys.find(key) != m_copied_keys.end()) {
		return true;
	}
	std::error_code ec;
	return fs::exists(dst, ec) && !ec && fs::file_size(dst, ec) == src.size && !ec;
}

archive_stats archiver::archive_file(const source_file &src) {
	archive_stats stats;
	const auto dst = destination_path(src);
	if(already_archived(src, dst)) {
		++stats.skipped;
		m_copied_keys.insert(copied_key(src));
		return stats;
	}

	if(!same_file_state(src.path, src.size, src.mtime)) {
		++stats.unstable;
		return stats;
	}

	std::error_code ec;
	fs::create_directories(dst.parent_path(), ec);
	if(ec) {
		std::cerr << "pcap_archiver: failed to create " << dst.parent_path() << ": " << ec.message() << std::endl;
		++stats.failed;
		return stats;
	}

	const auto tmp = dst.string() + ".tmp";
	fs::remove(tmp, ec);
	ec.clear();
	if(!copy_file_fsync(src.path, tmp)) {
		std::cerr << "pcap_archiver: failed to copy " << src.path << " to " << tmp
		          << ": " << std::strerror(errno) << std::endl;
		fs::remove(tmp, ec);
		++stats.failed;
		return stats;
	}

	if(!same_file_state(src.path, src.size, src.mtime)) {
		fs::remove(tmp, ec);
		++stats.unstable;
		return stats;
	}

	fs::rename(tmp, dst, ec);
	if(ec) {
		std::cerr << "pcap_archiver: failed to publish " << dst << ": " << ec.message() << std::endl;
		fs::remove(tmp, ec);
		++stats.failed;
		return stats;
	}
	fsync_directory(dst.parent_path());
	m_copied_keys.insert(copied_key(src));
	++stats.archived;
	return stats;
}

std::vector<archiver::archived_file> archiver::list_archived_files() const {
	std::vector<archived_file> out;
	std::error_code ec;
	if(!fs::exists(m_cfg.dest_dir, ec) || ec) {
		return out;
	}
	for(const auto &entry : fs::recursive_directory_iterator(m_cfg.dest_dir, ec)) {
		if(ec) {
			break;
		}
		if(!entry.is_regular_file(ec) || ec) {
			ec.clear();
			continue;
		}
		if(ends_with(entry.path().filename().string(), ".tmp")) {
			continue;
		}
		archived_file f;
		f.path = entry.path();
		f.size = entry.file_size(ec);
		if(ec) {
			ec.clear();
			continue;
		}
		f.mtime = entry.last_write_time(ec);
		if(ec) {
			ec.clear();
			continue;
		}
		out.push_back(std::move(f));
	}
	std::sort(out.begin(), out.end(), [](const archived_file &a, const archived_file &b) {
		if(a.mtime != b.mtime) {
			return a.mtime < b.mtime;
		}
		return a.path.string() < b.path.string();
	});
	return out;
}

archive_stats archiver::apply_retention() {
	archive_stats stats;
	auto files = list_archived_files();
	std::error_code ec;

	const auto retention = (m_cfg.retention_seconds > 0)
	                         ? std::chrono::seconds(m_cfg.retention_seconds)
	                         : std::chrono::hours(m_cfg.retention_hours);
	if(retention.count() > 0) {
		const auto cutoff = std::chrono::system_clock::now() - retention;
		for(const auto &file : files) {
			if(to_system_time(file.mtime) >= cutoff) {
				continue;
			}
			fs::remove(file.path, ec);
			if(!ec) {
				++stats.deleted;
			}
			ec.clear();
		}
		files = list_archived_files();
	}

	auto total_size = [&files]() {
		std::uintmax_t total = 0;
		for(const auto &file : files) {
			total += file.size;
		}
		return total;
	};

	std::size_t index = 0;
	if(m_cfg.max_used_bytes > 0) {
		while(total_size() > m_cfg.max_used_bytes && index < files.size()) {
			fs::remove(files[index].path, ec);
			if(!ec) {
				++stats.deleted;
				files[index].size = 0;
			}
			ec.clear();
			++index;
		}
	}

	if(m_cfg.min_free_bytes > 0) {
		index = 0;
		while(index < files.size()) {
			auto space = fs::space(m_cfg.dest_dir, ec);
			if(ec || space.available >= m_cfg.min_free_bytes) {
				break;
			}
			if(files[index].size == 0) {
				++index;
				continue;
			}
			fs::remove(files[index].path, ec);
			if(!ec) {
				++stats.deleted;
			}
			ec.clear();
			++index;
		}
	}

	return stats;
}

archive_stats archiver::scan_once() {
	archive_stats total;
	if(!m_cfg.enabled) {
		return total;
	}

	const auto retention_before = apply_retention();
	total.deleted += retention_before.deleted;

	const auto files = list_source_files();
	total.scanned += files.size();
	for(const auto &file : files) {
		auto stats = archive_file(file);
		total.archived += stats.archived;
		total.skipped += stats.skipped;
		total.unstable += stats.unstable;
		total.failed += stats.failed;
	}

	const auto retention_after = apply_retention();
	total.deleted += retention_after.deleted;
	return total;
}

int archiver::run() {
	if(!m_cfg.enabled) {
		std::cerr << "pcap_archiver: disabled" << std::endl;
		return 0;
	}
	for(;;) {
		scan_once();
		std::this_thread::sleep_for(std::chrono::milliseconds(m_cfg.poll_interval_ms));
	}
}

