	cp.add("no-append-mtime-suffix", 0, "keep original filename in archive unless it collides");
	cp.add("disable", 0, "disable archiver and exit");
	cp.add("once", 0, "scan once and exit");
	cp.parse_check(argc, argv);

	pcap_archive::config cfg;
	const auto config_path = cp.get<std::string>("config");
	if(!config_path.empty() && pcap_archive::load_config_file(config_path, cfg) != 0) {
		return 1;
	}

	if(cp.exist("disable")) cfg.enabled = false;
	if(!cp.get<std::string>("source-dir").empty()) cfg.source_dir = cp.get<std::string>("source-dir");
	if(!cp.get<std::string>("source-prefix").empty()) cfg.source_prefix = cp.get<std::string>("source-prefix");
	if(!cp.get<std::string>("dest-dir").empty()) cfg.dest_dir = cp.get<std::string>("dest-dir");
	if(cp.exist("retention-hours")) cfg.retention_hours = cp.get<std::uint32_t>("retention-hours");
	if(cp.exist("retention-seconds")) cfg.retention_seconds = cp.get<std::uint64_t>("retention-seconds");
	if(cp.exist("min-free-bytes")) cfg.min_free_bytes = cp.get<std::uint64_t>("min-free-bytes");
	if(cp.exist("max-used-bytes")) cfg.max_used_bytes = cp.get<std::uint64_t>("max-used-bytes");
	if(cp.exist("poll-interval-ms")) cfg.poll_interval_ms = cp.get<std::uint32_t>("poll-interval-ms");
	if(cp.exist("include-latest")) cfg.exclude_latest = false;
	if(cp.exist("no-append-mtime-suffix")) cfg.append_mtime_suffix = false;

	pcap_archive::archiver archiver(std::move(cfg));
	if(!archiver.get_config().enabled) {
		std::cerr << "pcap_archiver: disabled" << std::endl;
		return 0;
	}

	if(cp.exist("once")) {
		const auto stats = archiver.scan_once();
		std::cout << "pcap_archiver: scanned=" << stats.scanned
		          << " archived=" << stats.archived
		          << " skipped=" << stats.skipped
		          << " unstable=" << stats.unstable
		          << " failed=" << stats.failed
		          << " deleted=" << stats.deleted << std::endl;
		return stats.failed == 0 ? 0 : 1;
	}

	return archiver.run();
