	std::filesystem::path pipeline_status_file;
	std::filesystem::path pipeline_progress_file;
	bool stop_on_callback_failure{false};
};

class source {
public:
	virtual ~source() = default;
	virtual void set_callback(callback_t callback) = 0;
	virtual int run() = 0;
};

