int batch_tshark_source::run(tsv_sink &sink) {
	if(!m_input) {
		trace(0, "error: failed to create batch pcap input source");
		return 1;
	}
	m_input->set_callback([this, &sink](const std::filesystem::path &path) {
		return process_pcap(path, sink);
	});
	return m_input->run();
}

bool batch_tshark_source::process_pcap(const std::filesystem::path &path, tsv_sink &sink) {
	const std::string command = tshark::build_read_command(path, m_cfg.tshark, m_cfg.decode_as);
	// Keep the existing quoted command, including explicit stderr suppression.
	// exec makes source_pid identify tshark rather than an intermediate shell.
	const std::string shell_command = "exec " + command;
	int stdout_pipe[2]{-1, -1};
	int stderr_pipe[2]{-1, -1};
	if(pipe2(stdout_pipe, O_CLOEXEC) != 0 || pipe2(stderr_pipe, O_CLOEXEC) != 0) {
		for(int fd : {stdout_pipe[0], stdout_pipe[1], stderr_pipe[0], stderr_pipe[1]}) if(fd >= 0) close(fd);
		trace(0, "warn: failed to create tshark diagnostic pipes for %s", path.filename().string().c_str());
		return false;
	}
	const auto pid = fork();
	if(pid == 0) {
		dup2(stdout_pipe[1], STDOUT_FILENO);
		dup2(stderr_pipe[1], STDERR_FILENO);
		close(stdout_pipe[0]); close(stdout_pipe[1]); close(stderr_pipe[0]); close(stderr_pipe[1]);
		execl("/bin/sh", "sh", "-c", shell_command.c_str(), static_cast<char *>(nullptr));
		constexpr char error[] = "tshark shell exec failed\n";
		(void)::write(STDERR_FILENO, error, sizeof(error) - 1);
		_exit(127);
	}
	close(stdout_pipe[1]);
	close(stderr_pipe[1]);
	if(pid < 0) {
		close(stdout_pipe[0]); close(stderr_pipe[0]);
		trace(0, "warn: failed to start tshark for %s", path.filename().string().c_str());
		return false;
	}
	child_stderr_reader diagnostics;
	FILE *pipe = fdopen(stdout_pipe[0], "r");
	const bool logging_started = diagnostics.start(stderr_pipe[0], "tshark", pid);
	if(!pipe || !logging_started) {
		if(pipe) fclose(pipe); else close(stdout_pipe[0]);
		kill(pid, SIGTERM);
		while(waitpid(pid, nullptr, 0) < 0 && errno == EINTR) {}
		diagnostics.finish();
		trace(0, "warn: failed to start tshark diagnostic reader for %s", path.filename().string().c_str());
		return false;
	}

	std::array<char, 32768> line{};
	bool ok = true;
	if(fgets(line.data(), static_cast<int>(line.size()), pipe) == nullptr) {
		trace(1, "info: tshark output is empty for %s", path.filename().string().c_str());
	}
	else if(!sink.on_tsv_header(line.data())) {
		ok = false;
	}
	while(ok && fgets(line.data(), static_cast<int>(line.size()), pipe) != nullptr) {
		ok = sink.on_tsv_row(line.data());
	}
	sink.on_tsv_end();

	fclose(pipe);
	int status{};
	pid_t waited;
	do { waited = waitpid(pid, &status, 0); } while(waited < 0 && errno == EINTR);
	diagnostics.finish();
	if(waited < 0) {
		trace(0, "warn: waitpid failed for %s", path.filename().string().c_str());
		return false;
	}
	if(WIFEXITED(status) && WEXITSTATUS(status) == 0) return ok;
	if(WIFEXITED(status)) {
		trace(0, "warn: tshark failed for %s, exit_code=%d", path.filename().string().c_str(), WEXITSTATUS(status));
	}
	else if(WIFSIGNALED(status)) {
		trace(0, "warn: tshark terminated for %s, signal=%d", path.filename().string().c_str(), WTERMSIG(status));
	}
	else {
		trace(0, "warn: tshark ended unexpectedly for %s, status=%d", path.filename().string().c_str(), status);
	}
	return false;
}
