	int run() {
		if(!m_callback) {
			trace(0, "[ERROR] callback is not set");
			return 1;
		}

		int fd = inotify_init();
		if(fd < 0) {
			const int error = errno;
			trace(0, "inotify_init: path=%s errno=%d (%s)", m_config.watch_dir.c_str(), error, std::strerror(error));
			return 1;
		}

		int wd = inotify_add_watch(fd, m_config.watch_dir.c_str(), IN_CLOSE_WRITE);
		if(wd < 0) {
			const int error = errno;
			trace(0, "inotify_add_watch: path=%s errno=%d (%s)", m_config.watch_dir.c_str(), error, std::strerror(error));
			close(fd);
			return 1;
		}

		trace(1, "[START] Monitoring %s...", m_config.watch_dir.string().c_str());
		if(!rescan_pcaps()) {
			inotify_rm_watch(fd, wd);
			close(fd);
			return 1;
		}

		alignas(struct inotify_event) std::array<char, 16 * 1024> event_buf{};
		int result = 0;
		bool keep_running = true;
		while(keep_running) {
			ssize_t len = read(fd, event_buf.data(), event_buf.size());
			if(len <= 0) {
				const int error = len < 0 ? errno : 0;
				// SIGINT/SIGTERM interrupt this read during the existing stop path.
				if(len < 0 && error == EINTR) break;
				trace(0, "inotify read failed: path=%s errno=%d (%s) bytes=%zd",
				      m_config.watch_dir.c_str(), error, std::strerror(error), len);
				result = 1;
				break;
			}

			for(ssize_t offset = 0; offset < len;) {
				auto* event = reinterpret_cast<struct inotify_event*>(event_buf.data() + offset);
				offset += sizeof(struct inotify_event) + event->len;

				if(event->mask & IN_Q_OVERFLOW) {
					trace(0, "[WARN] inotify queue overflow, rescanning directory");
					if(!rescan_pcaps()) {
						result = 1;
						keep_running = false;
						break;
					}
					continue;
				}

				if(event->len > 0) {
					std::string filename = event->name;
					if(is_target_pcap(filename) && !m_processed_files.contains(filename)) {
						enqueue_pending(filename);
						if(!process_pending_pcaps()) {
							result = 1;
							keep_running = false;
							break;
						}
					}
				}
			}
		}

		inotify_rm_watch(fd, wd);
		close(fd);

		return result;
	}

private:
	bool is_target_pcap(const std::string& filename) const {
		return filename.find(m_config.pcap_prefix) != std::string::npos &&
		       filename.find(".pcap") != std::string::npos;
