export async function main() {
  await prepareStateDirectory(config.stateDir);
  diagnostic(`startup source=projected cwd=${process.cwd()} root=${config.rootDir} logDir=${config.logDir} port=${config.port}`);
  diagnosticInputs();

  const app = fastify({ logger: config.httpAccessLog });
  const alertsSettings = config.stmConfigFile ? new AlertsSettings(config.stmConfigFile) : undefined;
  const protocolMapSettings = config.stmConfigFile ? new ProtocolMapSettings(config.stmConfigFile) : undefined;
  const capturePolicySettings = new CapturePolicySettings(config.capturePolicyFile);
  const captureSettings = config.stmConfigFile ? new CaptureSettings(config.stmConfigFile, () => capturePolicySettings.get()) : undefined;
  const setupSettings = captureSettings && protocolMapSettings && alertsSettings ? new SetupSettings(capturePolicySettings, captureSettings, protocolMapSettings, alertsSettings) : undefined;
  const setupProfiles = new SetupProfiles(config.setupProfilesFile);
  const processControl = new ProcessControlClient(config.processControlSocket);
  const runtimeActivation = new RuntimeActivation(config.runtimeActivationFile);
  const maintenanceSettings = await MaintenanceSettings.load({
    definitionFile: config.maintenanceSettingsDefinitionFile,
    runtimeFile: config.runtimeSettingsFile,
    defaults: { lostRetentionSec: config.lostRetentionSec, historyWindowSec: config.historyWindowSec, staleAfterSec: config.staleAfterSec, diagnosticLog: config.diagnosticLog, dashboardLayoutEditMode: config.dashboardLayoutEditMode, streamsErrorCountMode: config.streamsErrorCountMode, streamsRecentAlertRetentionMin: config.streamsRecentAlertRetentionMin, streamsAlertDisplay: config.streamsAlertDisplay, historicalSparklines: config.historicalSparklines, streamsSparklineSamples: config.streamsSparklineSamples, tooltipDelayMs: config.tooltipDelayMs }
  });
  Object.assign(config, maintenanceSettings.get().values);
  const store = new StreamStore(config.historyWindowSec, config.timelineWindowSec, config.lostRetentionSec, config.maxEvents, config.maxTimelineRows, config.topologyStaleRetentionSec, config.topologyMaxStaleEdges, config.topologyMaxDetailFlowsPerRelation, config.streamsErrorCountMode, config.streamsSparklineSamples, dataNowSec);
  const captureHealth = new CaptureHealthStore(config.captureHealthStaleAfterSec, dataNowSec);
  const now = dataNowSec();
  const initialEvents = await queryEventsHistory({ from: now - 24 * 3600, to: now, limit: config.maxEvents });
  for (const event of initialEvents.reverse()) store.addEvent(event);

  const initialTopology = await queryProjectedTopologyAt({ checkpointDir: config.topologyCheckpointDir, updatesDir: config.topologyUpdatesDir, time: now });
  if (initialTopology) store.applyTopologySnapshot(initialTopology);
  diagnostic(`initial state events=${store.listEvents({ limit: config.maxEvents }).length} topology=${initialTopology ? "loaded" : "missing"}`);

  const sockets = new SocketServer(app.server, store, captureHealth, config.streamsPatchIntervalMs, config.wsMaxBufferedBytes);
  await registerRoutes(app, store, maintenanceSettings, alertsSettings, protocolMapSettings, capturePolicySettings, captureSettings, setupSettings, setupProfiles, captureHealth, runtimeActivation, processControl, (values) => {
    Object.assign(config, values);
    store.updateRuntimeConfig(values);
    sockets.broadcastConfig(values);
  });
  if (existsSync(config.externalPagesDir)) {
    await app.register(fastifyStatic, { root: config.externalPagesDir, prefix: "/external-pages/", decorateReply: false });
  }
  if (existsSync(config.localesDir)) {
    await app.register(fastifyStatic, { root: config.localesDir, prefix: "/locales/", decorateReply: false, setHeaders: (response) => response.setHeader("Cache-Control", "no-store") });
  }
  if (existsSync(config.clientDist)) {
    await app.register(fastifyStatic, { root: config.clientDist, prefix: "/" });
    app.setNotFoundHandler((request, reply) => {
      if (request.raw.url?.startsWith("/api") || request.raw.url === "/ws" || request.raw.url?.startsWith("/external-pages/") || request.raw.url?.startsWith("/locales/")) return reply.code(404).send({ error: "not found" });
      return reply.sendFile("index.html");
    });
  }

  sockets.start();
  const { tails, flushMetrics } = await createProjectedTails(app, store, sockets, captureHealth);
  tails.forEach((tail) => tail.start());
  const close = async () => { flushMetrics(); tails.forEach((tail) => tail.stop()); await app.close(); };
  process.on("SIGINT", () => void close());
  process.on("SIGTERM", () => void close());
  try { await app.listen({ host: config.host, port: config.port }); }
  catch (error) { throw new OperationError("listen", { host: config.host, port: config.port }, error); }
}

async function createProjectedTails(app: FastifyInstance, store: StreamStore, sockets: SocketServer, captureHealth: CaptureHealthStore): Promise<{ tails: RunningTail[]; flushMetrics: () => void }> {
  const state = await loadProjectedStreamState(config.streamStateDir, Number.POSITIVE_INFINITY);
  const applyStreams = (time: number, dropPreviousRun = false) => store.applyStreamSnapshot(materializeProjectedStreamStates(state.streams, time), time, dropPreviousRun);
  if (state.hasRecords) applyStreams(dataNowSec());

  const streams = new RotatingNdjsonTail({ root: `${config.streamStateDir}/delta`, extension: ".ndjson", pollMs: config.pollMs, startAtLatestFile: true,
