import { readFileSync } from "node:fs";
import { config } from "./config";

export type PlaybackStatus = {
  mode: "current" | "original";
  state: "playing" | "paused" | "finished" | "stopped";
  speed: number;
  sourceFirst: number;
  sourceLast: number;
  now: number;
  loop: boolean;
  cycle: number;
  loopGapSec: number;
};

type PlayerState = {
  schema_version: number;
  mode: PlaybackStatus["mode"];
  state: PlaybackStatus["state"];
  speed: number;
  source_first: number;
  source_last: number;
  current_time: number;
  updated_wall: number;
  loop?: boolean;
  cycle?: number;
  loop_gap?: number;
};

export function playbackEnabled() { return Boolean(config.playbackStateFile); }

export function playbackStatus(): PlaybackStatus | null {
  if (!config.playbackStateFile) return null;
  try {
    const state = JSON.parse(readFileSync(config.playbackStateFile, "utf8")) as PlayerState;
    if (state.schema_version !== 1 || !["current", "original"].includes(state.mode) ||
      !["playing", "paused", "finished", "stopped"].includes(state.state) ||
      !Number.isFinite(state.speed) || state.speed <= 0 || !Number.isFinite(state.current_time) ||
      !Number.isFinite(state.updated_wall) ||
      (state.loop !== undefined && typeof state.loop !== "boolean") ||
      (state.cycle !== undefined && (!Number.isSafeInteger(state.cycle) || state.cycle < 0)) ||
      (state.loop_gap !== undefined && (!Number.isFinite(state.loop_gap) || state.loop_gap <= 0))) return null;
    const elapsed = Math.max(0, Date.now() / 1000 - state.updated_wall);
    const now = state.state === "playing"
      ? state.mode === "original" ? Math.min(state.source_last, state.current_time + elapsed * state.speed) : state.current_time + elapsed
      : state.current_time;
    return { mode: state.mode, state: state.state, speed: state.speed,
      sourceFirst: state.source_first, sourceLast: state.source_last, now,
      loop: state.loop ?? false, cycle: state.cycle ?? 0, loopGapSec: state.loop_gap ?? 1 };
  } catch { return null; }
}

export function dataNowSec() {
  const status = playbackStatus();
  return status?.mode === "original" ? status.now : Date.now() / 1000;
}
export type PlaybackStatus = {
  enabled: true;
  mode: "current" | "original";
  state: "playing" | "paused" | "finished" | "stopped";
  speed: number;
  sourceFirst: number;
  sourceLast: number;
  now: number;
  loop: boolean;
  cycle: number;
  loopGapSec: number;
};

let anchor: { status: PlaybackStatus; receivedWall: number } | null = null;

export function setPlaybackStatus(status: PlaybackStatus | null) {
  anchor = status ? { status, receivedWall: Date.now() / 1000 } : null;
}

export function dataNowSec() {
  if (!anchor || anchor.status.mode !== "original") return Date.now() / 1000;
  const { status, receivedWall } = anchor;
  return status.state === "playing"
    ? Math.min(status.sourceLast, status.now + Math.max(0, Date.now() / 1000 - receivedWall) * status.speed)
    : status.now;
}
