import type { FastifyInstance } from "fastify";
import type { WsMessage } from "../types";

// Common API/store/socket code consumes this contract, not input-specific state.
export interface AnalysisSource {
  nowSec(): number;
  readonly runtimeMutationError?: string;
  registerRoutes(app: FastifyInstance): void;
  statusMessages(): WsMessage[];
}

import type { AnalysisSource } from "./analysisSource";
import { createLiveSource } from "./liveSource";
import { createPlaybackSource } from "./playbackSource";

// Input selection belongs at application startup, outside the common API/store.
export function createAnalysisSource(playbackStateFile?: string): AnalysisSource {
  return playbackStateFile ? createPlaybackSource(playbackStateFile) : createLiveSource();
}

import type { AnalysisSource } from "./analysisSource";

export function createLiveSource(wallNowSec = () => Date.now() / 1000): AnalysisSource {
  return {
    nowSec: wallNowSec,
    registerRoutes(app) {
      // Preserve the existing discovery endpoint for clients.
      app.get("/api/playback", async () => ({ enabled: false }));
    },
    statusMessages: () => []
  };
}

