const { test } = require('node:test');
const assert = require('node:assert/strict');
const { clientBrowser } = require('./helpers/client-browser.cjs');

test('common source hook and badge follow the selected adapter through recorded/live transitions', async t => {
  const browser = await clientBrowser(t, `
    import React from 'react';
    import {createRoot} from 'react-dom/client';
    import {createDataClock,dataNowSec} from './client/src/dataClock';
    import {selectAnalysisSource} from './client/src/analysisSource';
    import {createPlaybackSource} from './client/src/sources/playbackSource';
    import {useAnalysisSource} from './client/src/hooks/useAnalysisSource';
    import {AnalysisSourceBadge} from './client/src/components/AnalysisSourceBadge';
    window.wall=1000;
    window.status={enabled:true,mode:'original',state:'playing',speed:2,
      sourceFirst:100,sourceLast:200,now:110,loop:true,cycle:1,loopGapSec:1};
    window.source=createPlaybackSource(async()=>window.status,createDataClock(()=>window.wall));
    selectAnalysisSource(window.source);
    function Fixture(){const view=useAnalysisSource();
      return <main data-advancing={String(view.advancing)} data-time={dataNowSec()}>
        <AnalysisSourceBadge badge={view.badge}/></main>;
    }
    createRoot(document.getElementById('root')).render(<Fixture/>);
  `);
  if (!browser) return;
  const { wait, evaluate, errors } = browser;
  await wait("document.querySelector('[aria-label=\"Replay mode\"]')?.textContent.includes('LOOP 2')");
  assert.equal(await evaluate("document.querySelector('main').dataset.time"), '110');
  await evaluate("wall+=3;status={...status,state:'paused',now:120};source.handleMessage({type:'playback:status',playback:status})");
  await wait("document.querySelector('main').dataset.advancing==='false'");
  assert.equal(await evaluate("document.querySelector('main').dataset.time"), '120');
  await evaluate('wall=2000;status=null');
  await wait("!document.querySelector('[aria-label=\"Replay mode\"]')&&document.querySelector('main').dataset.time==='2000'");
  assert.equal(await evaluate("document.querySelector('main').dataset.advancing"), 'true');
  assert.deepEqual(errors, []);
});

