int optional_index(const field_map_t &fields, std::string_view name) {
	auto it = fields.find(std::string(name));
	if(it == fields.end()) {
		return -1;
	}
	return static_cast<int>(it->second);
}

bool require_index(const field_map_t &fields, std::string_view name, int &out) {
	out = optional_index(fields, name);
	if(out < 0) {
