  for (const operationId of operationIds) {
    try {
      await runtimeActivation.reconcile(await processControl.operation(operationId));
    } catch { /* The status response below reports unavailable control separately. */ }
  }
  activation = await runtimeActivation.snapshot();
  try {
    const statuses = await processControl.status();
    activation = await runtimeActivation.reconcileObserved(statuses);
    return {
      control: { available: true },
