std::unique_ptr<tsv_source> tsv_input::make_source(config cfg) {
	if(cfg.mode == processing_mode::continuous) {
		return std::make_unique<continuous_tshark_source>(continuous_tshark_source::config{
			.input = std::move(cfg.input), .tshark = std::move(cfg.tshark),
			.decode_as = std::move(cfg.decode_as)});
	}
	return std::make_unique<batch_tshark_source>(batch_tshark_source::config{
		.input = std::move(cfg.input), .tshark = std::move(cfg.tshark),
		.decode_as = std::move(cfg.decode_as)});
}
