namespace {
bool write_all(int fd, const char *data, std::size_t size) {
	while(size > 0) {
		const auto n = ::write(fd, data, size);
		if(n < 0) {
			if(errno == EINTR) continue;
			return false;
		}
		data += n;
		size -= static_cast<std::size_t>(n);
	}
	return true;
}
} // namespace

continuous_tshark_source::continuous_tshark_source(config cfg)
	: m_cfg(std::move(cfg)) {
	m_cfg.input.stop_on_callback_failure = true;
	m_input = pcap_input::make_source(m_cfg.input);
}

continuous_tshark_source::~continuous_tshark_source() {
	stop();
}

int continuous_tshark_source::run(tsv_sink &sink) {
	if(m_cfg.input.input_mode != pcap_input::mode::watch_dir) {
		trace(0, "error: continuous input requires watch_dir mode");
		return 1;
	}
	if(!m_input || !start(sink)) return 1;
	m_input->set_callback([this](const std::filesystem::path &path) {
		return process_pcap(path);
	});
	const int rc = m_input->run();
	stop();
	return rc == 0 && m_reader_ok ? 0 : 1;
}

bool continuous_tshark_source::start(tsv_sink &sink) {
	// A terminated tshark must turn a subsequent pipe write into a recoverable error.
	signal(SIGPIPE, SIG_IGN);
	int stdin_pipe[2]{-1, -1};
	int stdout_pipe[2]{-1, -1};
	int stderr_pipe[2]{-1, -1};
	if(pipe2(stdin_pipe, O_CLOEXEC) != 0 || pipe2(stdout_pipe, O_CLOEXEC) != 0 || pipe2(stderr_pipe, O_CLOEXEC) != 0) {
		trace(0, "error: failed to create tshark pipes: %s", std::strerror(errno));
		for(int fd : {stdin_pipe[0], stdin_pipe[1], stdout_pipe[0], stdout_pipe[1], stderr_pipe[0], stderr_pipe[1]}) if(fd >= 0) close(fd);
		return false;
	}
	const auto argv_values = tshark::build_continuous_argv(m_cfg.tshark, m_cfg.decode_as);
	std::vector<char *> argv;
	argv.reserve(argv_values.size() + 1);
	for(const auto &value : argv_values) argv.push_back(const_cast<char *>(value.c_str()));
	argv.push_back(nullptr);

	const auto pid = fork();
	if(pid == 0) {
		dup2(stdin_pipe[0], STDIN_FILENO);
		dup2(stdout_pipe[1], STDOUT_FILENO);
		dup2(stderr_pipe[1], STDERR_FILENO);
		close(stdin_pipe[0]); close(stdin_pipe[1]);
		close(stdout_pipe[0]); close(stdout_pipe[1]);
		close(stderr_pipe[0]); close(stderr_pipe[1]);
		execvp(argv[0], argv.data());
		constexpr char error[] = "tshark exec failed\n";
		(void)::write(STDERR_FILENO, error, sizeof(error) - 1);
		_exit(127);
	}
	if(pid < 0) {
		trace(0, "error: failed to start tshark: %s", std::strerror(errno));
		close(stdin_pipe[0]); close(stdin_pipe[1]); close(stdout_pipe[0]); close(stdout_pipe[1]);
		close(stderr_pipe[0]); close(stderr_pipe[1]);
		return false;
	}
	close(stdin_pipe[0]);
	close(stdout_pipe[1]);
	close(stderr_pipe[1]);
	m_pid = pid;
	m_stdin_fd = stdin_pipe[1];
	m_stdout_fd = stdout_pipe[0];
	if(!m_diagnostics.start(stderr_pipe[0], "tshark", pid)) {
		trace(0, "error: failed to start tshark diagnostic reader");
		stop();
		return false;
	}
	m_reader_ok = true;
	m_reader = std::thread([this, &sink] { read_output(sink); });
	return true;
}

bool continuous_tshark_source::process_pcap(const std::filesystem::path &path) {
	if(!m_reader_ok || m_stdin_fd < 0) return false;
	int status{};
	pid_t waited;
	do { waited = waitpid(m_pid, &status, WNOHANG); } while(waited < 0 && errno == EINTR);
	if(waited < 0) {
		const int error = errno;
		trace(0, "warn: continuous tshark waitpid failed: path=%s errno=%d (%s)",
		      path.c_str(), error, std::strerror(error));
		return false;
	}
	if(waited == m_pid) {
		if(WIFEXITED(status)) {
			trace(0, "warn: continuous tshark exited before %s, exit_code=%d", path.c_str(), WEXITSTATUS(status));
		}
		else if(WIFSIGNALED(status)) {
			trace(0, "warn: continuous tshark terminated before %s, signal=%d", path.c_str(), WTERMSIG(status));
		}
		m_pid = -1;
		return false;
	}
	std::vector<char> bytes;
	std::string error;
	if(!m_streamer.append(path, bytes, error)) {
		trace(0, "warn: continuous pcap streamer failed: %s", error.c_str());
		return false;
	}
	if(bytes.empty()) return true;
	if(!write_all(m_stdin_fd, bytes.data(), bytes.size())) {
		const int error_code = errno;
		trace(0, "warn: failed to write pcap stream: path=%s errno=%d (%s)", path.c_str(), error_code, std::strerror(error_code));
		return false;
	}
	return true;
}

void continuous_tshark_source::read_output(tsv_sink &sink) {
	FILE *stream = fdopen(m_stdout_fd, "r");
	if(!stream) {
		m_reader_ok = false;
		return;
	}
	m_stdout_fd = -1;
	std::array<char, 32768> line{};
	if(fgets(line.data(), static_cast<int>(line.size()), stream) != nullptr) {
		m_reader_ok = sink.on_tsv_header(line.data());
	}
	else {
		m_reader_ok = false;
	}
	while(m_reader_ok && fgets(line.data(), static_cast<int>(line.size()), stream) != nullptr) {
		m_reader_ok = sink.on_tsv_row(line.data());
	}
	sink.on_tsv_end();
	fclose(stream);
}

void continuous_tshark_source::stop() {
	if(m_stdin_fd >= 0) {
		close(m_stdin_fd);
		m_stdin_fd = -1;
	}
	if(m_pid > 0) {
		kill(m_pid, SIGTERM);
		int status{};
		waitpid(m_pid, &status, 0);
		m_pid = -1;
	}
	if(m_reader.joinable()) m_reader.join();
	m_diagnostics.finish();
	if(m_stdout_fd >= 0) {
		close(m_stdout_fd);
		m_stdout_fd = -1;
	}
}
#include "pcap_input_adapters.h"

