import json
import os
from pathlib import Path
import signal
import subprocess
import sys
import tempfile
import time
import unittest


class PcapInputErrorsTests(unittest.TestCase):
    def run_watch_case(self, initial_error=False, runtime_error=False, stop_signal=signal.SIGTERM):
        with tempfile.TemporaryDirectory(prefix="stm-input-errors-") as directory:
            root = Path(directory)
            watch = root / "capture"
            watch.mkdir()
            ready = root / "mock-ready"
            status = root / "pipeline.ndjson"
            mock = root / "mock-tshark"
            mock.write_text("#!" + sys.executable + "\n" + """
import os, sys
from pathlib import Path
fields = [sys.argv[i + 1] for i, arg in enumerate(sys.argv[:-1]) if arg == '-e']
print('\t'.join(fields), flush=True)
Path(os.environ['STM_INPUT_TEST_READY']).touch()
while os.read(0, 65536):
    pass
""")
            mock.chmod(0o700)
            config = root / "config.json"
            config.write_text(json.dumps({
                "logs": {"dir": str(root / "logs")},
                "input": {"watch_dir": str(watch), "processing_mode": "continuous"},
                "capture_health": {"pipeline_status_file": str(status)},
                "tshark": {"program": str(mock), "redirect_stderr": False},
            }))
            if initial_error:
                (watch / "cap_00001.pcapng").write_bytes(b"invalid pcapng")
                (watch / "cap_00002.pcapng").touch()
            env = {**os.environ, "STM_INPUT_TEST_READY": str(ready),
                   "STM_LOG_LEVEL_FILE": str(root / "log-levels.json")}
            with subprocess.Popen([os.environ["STM_INPUT_ERRORS_TEST_BIN"], "--config", str(config)],
                                  cwd=root, env=env, stdout=subprocess.DEVNULL,
                                  stderr=subprocess.PIPE, text=True) as child:
                try:
                    if not initial_error:
                        deadline = time.monotonic() + 8
                        while not (ready.exists() and status.exists()):
                            if child.poll() is not None:
                                self.fail("STM exited before watcher was ready: " + child.communicate()[1])
                            if time.monotonic() > deadline:
                                self.fail("watcher readiness timed out")
                            time.sleep(0.01)
                        if runtime_error:
                            (watch / "cap_00001.pcapng").write_bytes(b"invalid pcapng")
                        else:
                            child.send_signal(stop_signal)
                    _, stderr = child.communicate(timeout=10)
                finally:
                    if child.poll() is None:
                        child.kill()
                        child.communicate(timeout=5)
            self.assertEqual(child.returncode, 1 if initial_error or runtime_error else 0, stderr)
            if initial_error or runtime_error:
                self.assertIn("continuous pcap streamer failed", stderr)
                self.assertIn("pcap callback failed", stderr)
                self.assertIn(str(watch / "cap_00001.pcapng"), stderr)

    def test_initial_pcap_failure_returns_one(self):
        self.run_watch_case(initial_error=True)

    def test_runtime_pcap_failure_returns_one(self):
        self.run_watch_case(runtime_error=True)

    def test_operator_stops_return_zero(self):
        for stop_signal in (signal.SIGINT, signal.SIGTERM):
            with self.subTest(signal=stop_signal):
                self.run_watch_case(stop_signal=stop_signal)

    def test_caught_exception_returns_one(self):
        with tempfile.TemporaryDirectory(prefix="stm-input-exception-") as directory:
            root = Path(directory)
            not_a_directory = root / "log-file"
            not_a_directory.touch()
            config = root / "config.json"
            config.write_text(json.dumps({"logs": {"dir": str(not_a_directory)}}))
            result = subprocess.run([os.environ["STM_INPUT_ERRORS_TEST_BIN"], "--config", str(config)],
                                    cwd=root, capture_output=True, text=True, timeout=10,
                                    env={**os.environ, "STM_LOG_LEVEL_FILE": str(root / "log-levels.json")})
            self.assertEqual(result.returncode, 1, result.stderr)
            self.assertIn("error:", result.stderr)
            self.assertIn(str(not_a_directory), result.stderr)


if __name__ == "__main__":
    unittest.main()
#!/bin/sh
set -eu

script_dir=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
project_root=$(CDPATH= cd -- "$script_dir/.." && pwd)
supervisor_config="$project_root/docker/supervisord.player.conf"

usage() {
    cat <<'EOF'
Usage: scripts/stm-player-supervisor --output DIR [options] up|status|pause|resume|stop|shutdown

  up        Start an isolated supervisord with player paused, then projector and FE.
  status    Show the three supervised processes.
  pause     Pause the running player.
  resume    Start or resume playback after the other processes are ready.
  stop      Stop playback; projector and FE remain available.
  shutdown  Stop all three processes and wait for the dedicated supervisord to exit.

Options for up:
  --source DIR          Immutable directory containing event-journal and metrics-journal.
  --time-mode MODE      current (default) or original.
  --speed NUMBER        Positive playback speed (default: 1).
  --loop                Repeat continuously (current mode only).
  --loop-gap SECONDS    Positive wall-time gap between cycles (default: 1).
  --host HOST           FE bind host (default: 127.0.0.1).
  --port PORT           FE port (default: 3100).

Environment overrides: STM_BIN_DIR, STM_CONFIG_DIR, STM_FE_DIR, STM_NODE_BIN,
STM_REPLAY_SOURCE_DIR, STM_REPLAY_OUTPUT_DIR, STM_REPLAY_RUNTIME_DIR,
STM_REPLAY_STATE_DIR, STM_REPLAY_TIME_MODE, STM_REPLAY_SPEED,
STM_REPLAY_LOOP, STM_REPLAY_LOOP_GAP, STM_REPLAY_HOST, STM_REPLAY_PORT.
Each run needs a new empty output directory. The supervisor socket, logs and
FE state use separate sibling directories by default.
EOF
}

source_dir=${STM_REPLAY_SOURCE_DIR:-}
output_dir=${STM_REPLAY_OUTPUT_DIR:-}
time_mode=${STM_REPLAY_TIME_MODE:-current}
speed=${STM_REPLAY_SPEED:-1}
loop_enabled=${STM_REPLAY_LOOP:-0}
loop_gap=${STM_REPLAY_LOOP_GAP:-1}
fe_host=${STM_REPLAY_HOST:-127.0.0.1}
fe_port=${STM_REPLAY_PORT:-3100}

while [ "$#" -gt 0 ]; do
    case "$1" in
        --source|--output|--time-mode|--speed|--loop-gap|--host|--port)
            [ "$#" -ge 2 ] || { echo "missing value for $1" >&2; exit 2; }
            case "$1" in
                --source) source_dir=$2 ;;
                --output) output_dir=$2 ;;
                --time-mode) time_mode=$2 ;;
                --speed) speed=$2 ;;
                --loop-gap) loop_gap=$2 ;;
                --host) fe_host=$2 ;;
                --port) fe_port=$2 ;;
            esac
            shift 2
            ;;
        --loop) loop_enabled=1; shift ;;
        -h|--help) usage; exit 0 ;;
        --) shift; break ;;
        -*) echo "unknown option: $1" >&2; usage >&2; exit 2 ;;
        *) break ;;
    esac
done

[ "$#" -eq 1 ] || { usage >&2; exit 2; }
action=$1
case "$action" in up|status|pause|resume|stop|shutdown) ;; *) usage >&2; exit 2 ;; esac
[ -n "$output_dir" ] || { echo "--output is required" >&2; exit 2; }

safe_path() {
    case "$1" in
        /*) ;;
        *) return 1 ;;
    esac
    case "$1" in
        *[!A-Za-z0-9_./-]*) return 1 ;;
    esac
}

safe_number() {
    awk -v value="$1" 'BEGIN { if (value !~ /^[0-9]+([.][0-9]+)?$/ || value + 0 <= 0) exit 1 }'
}

safe_path "$output_dir" || { echo "output must be an absolute path without spaces or special characters" >&2; exit 2; }
output_dir=$(realpath -m -- "$output_dir")
[ "$output_dir" != / ] || { echo "replay output cannot be the filesystem root" >&2; exit 2; }
runtime_dir=${STM_REPLAY_RUNTIME_DIR:-"$output_dir.supervisor"}
state_dir=${STM_REPLAY_STATE_DIR:-"$output_dir.fe-state"}
safe_path "$runtime_dir" || { echo "invalid supervisor runtime directory" >&2; exit 2; }
safe_path "$state_dir" || { echo "invalid FE state directory" >&2; exit 2; }
runtime_dir=$(realpath -m -- "$runtime_dir")
state_dir=$(realpath -m -- "$state_dir")

case "$output_dir" in /tmp/stm|/tmp/stm/*) echo "refusing to use production /tmp/stm" >&2; exit 2 ;; esac
for separate_dir in "$runtime_dir" "$state_dir"; do
    case "$separate_dir" in
        "$output_dir"|"$output_dir"/*) echo "runtime and FE state must be outside the replay output" >&2; exit 2 ;;
    esac
    case "$output_dir" in
        "$separate_dir"|"$separate_dir"/*) echo "replay output must be separate from runtime and FE state" >&2; exit 2 ;;
    esac
done
case "$runtime_dir" in "$state_dir"|"$state_dir"/*) echo "runtime and FE state must be separate" >&2; exit 2 ;; esac
