bool read_file(const std::filesystem::path &path, std::vector<char> &data, std::string &error) {
	auto fail = [&](const char *stage, int code, const std::string &detail = "") {
		error = "failed to read " + path.string() + ": stage=" + stage +
		        " errno=" + std::to_string(code) + " (" + std::strerror(code) + ")" + detail;
		return false;
	};
	const int fd = ::open(path.c_str(), O_RDONLY | O_CLOEXEC);
	if(fd < 0) return fail("open", errno);
	struct file_guard {
		int fd;
		~file_guard() { ::close(fd); }
	} guard{fd};
	struct stat status{};
	if(::fstat(fd, &status) != 0) return fail("fstat", errno);
	if(!S_ISREG(status.st_mode)) return fail("fstat", 0, " reason=not_regular_file");
	if(status.st_size < 0 || static_cast<std::uintmax_t>(status.st_size) > data.max_size()) {
		return fail("size", 0, " reason=unsupported_file_size");
	}
	data.resize(static_cast<std::size_t>(status.st_size));
	std::size_t received = 0;
	while(received < data.size()) {
		const auto remaining = std::min(data.size() - received,
		                                static_cast<std::size_t>(std::numeric_limits<ssize_t>::max()));
		const auto count = ::read(fd, data.data() + received, remaining);
		if(count < 0 && errno == EINTR) continue;
		if(count <= 0) {
			const int code = count < 0 ? errno : 0;
			return fail("read", code, " expected_bytes=" + std::to_string(data.size()) +
			            " read_bytes=" + std::to_string(received) +
			            (count == 0 ? " reason=unexpected_eof" : ""));
		}
		received += static_cast<std::size_t>(count);
	}
	return true;
}
} // namespace

void pcap_streamer::reset() {
	m_initialized = false;
	m_interfaces.clear();
}

bool pcap_streamer::append(const std::filesystem::path &path, std::vector<char> &out, std::string &error) {
	std::vector<char> data;
	if(!read_file(path, data, error)) return false;
	if(data.size() < 12 || read_u32(data.data()) != section_header_block || read_u32(data.data() + 8) != 0x1a2b3c4d) {
		error = "unsupported or invalid little-endian pcapng: " + path.string();
		return false;
	}

	std::vector<std::vector<char>> interfaces;
	std::size_t offset = 0;
	bool seen_packet = false;
	std::vector<char> emitted;
	while(offset + 12 <= data.size()) {
		const auto type = read_u32(data.data() + offset);
		const auto length = read_u32(data.data() + offset + 4);
		if(length < 12 || offset + length > data.size() || read_u32(data.data() + offset + length - 4) != length) {
			error = "invalid pcapng block length: " + path.string();
			return false;
		}
		const char *block = data.data() + offset;
		if(type == interface_description_block) {
			if(seen_packet) {
				error = "pcapng interface block after packets: " + path.string();
				return false;
			}
			interfaces.emplace_back(block, block + length);
			if(!m_initialized) emitted.insert(emitted.end(), block, block + length);
		}
		else if(type == enhanced_packet_block || type == simple_packet_block) {
			seen_packet = true;
			emitted.insert(emitted.end(), block, block + length);
		}
		else if(!m_initialized && (type == section_header_block || type == interface_description_block)) {
			emitted.insert(emitted.end(), block, block + length);
		}
		offset += length;
	}
	if(offset != data.size() || interfaces.empty()) {
		error = "pcapng has no complete interface definition: " + path.string();
		return false;
	}
	if(!m_initialized) {
		m_interfaces = std::move(interfaces);
		m_initialized = true;
	}
	else if(interfaces != m_interfaces) {
		error = "pcapng interface definitions changed: " + path.string();
		return false;
	}
	out.insert(out.end(), emitted.begin(), emitted.end());
	return true;
}

