	fclose(stream);
}

void continuous_tshark_source::stop() {
	if(m_stdin_fd >= 0) {
		close(m_stdin_fd);
		m_stdin_fd = -1;
	}
	if(m_pid > 0) {
		kill(m_pid, SIGTERM);
		int status{};
		waitpid(m_pid, &status, 0);
		m_pid = -1;
	}
	if(m_reader.joinable()) m_reader.join();
	m_diagnostics.finish();
	if(m_stdout_fd >= 0) {
		close(m_stdout_fd);
		m_stdout_fd = -1;
	}
}
