#include <mutex>
#include <thread>

#include "json.h"

// Publishes progress independently of packet arrival and PCAP watcher callbacks.
class pipeline_progress {
public:
	struct config {
		std::filesystem::path output_file;
		double publish_interval_sec{1.0};
	};

	explicit pipeline_progress(config cfg);
	~pipeline_progress();
	void start();
	void stop();
	void record_tshark_packet();
	void record_processed_packet(double packet_time_epoch);

private:
	void run(std::stop_token stop);
	bool write_snapshot(const json &snapshot) const;

	config m_cfg;
	std::mutex m_mutex;
	std::condition_variable m_wakeup;
	std::uint64_t m_tshark_packets{};
	std::uint64_t m_processed_packets{};
	double m_last_processed_packet_time{};
	std::jthread m_worker;
};

#endif /* PIPELINE_PROGRESS_H */
#include "pipeline_progress.h"

#include <chrono>
#include <cmath>
#include <fstream>
#include <stdexcept>
#include <utility>

#include <unistd.h>

#include "trace.h"

pipeline_progress::pipeline_progress(config cfg)
	: m_cfg(std::move(cfg)) {
	if(!std::isfinite(m_cfg.publish_interval_sec) || m_cfg.publish_interval_sec <= 0.0) {
		throw std::invalid_argument("pipeline progress interval must be positive and finite");
	}
}

pipeline_progress::~pipeline_progress() {
	stop();
}

void pipeline_progress::start() {
	stop();
	{
		std::lock_guard lock(m_mutex);
		m_tshark_packets = 0;
		m_processed_packets = 0;
		m_last_processed_packet_time = 0.0;
	}
	if(!m_cfg.output_file.empty()) {
		m_worker = std::jthread([this](std::stop_token stop) { run(stop); });
	}
}

void pipeline_progress::stop() {
	if(m_worker.joinable()) {
		{
			std::lock_guard lock(m_mutex);
			m_worker.request_stop();
		}
		m_wakeup.notify_all();
		m_worker.join();
	}
}

void pipeline_progress::record_tshark_packet() {
	std::lock_guard lock(m_mutex);
	++m_tshark_packets;
}

void pipeline_progress::record_processed_packet(double packet_time_epoch) {
	std::lock_guard lock(m_mutex);
	++m_processed_packets;
	if(std::isfinite(packet_time_epoch) && packet_time_epoch > 0.0) {
		m_last_processed_packet_time = packet_time_epoch;
	}
}

void pipeline_progress::run(std::stop_token stop) {
	auto previous = std::chrono::steady_clock::now();
	std::uint64_t previous_tshark = 0, previous_processed = 0;
	bool first = true, write_failed = false;
	std::unique_lock lock(m_mutex);
	while(true) {
		if(!first) {
			m_wakeup.wait_for(lock, std::chrono::duration<double>(m_cfg.publish_interval_sec),
				[&stop] { return stop.stop_requested(); });
		}
		const auto now = std::chrono::steady_clock::now();
		const double elapsed = std::chrono::duration<double>(now - previous).count();
		const auto observed_at = std::chrono::duration<double>(std::chrono::system_clock::now().time_since_epoch()).count();
		json snapshot{
			{"schema_version", 1}, {"record_type", "pcap_pipeline_progress"},
			{"pid", getpid()}, {"progress_observed_at", observed_at},
			{"last_processed_packet_time", m_last_processed_packet_time > 0.0 ? json(m_last_processed_packet_time) : json(nullptr)},
			{"tshark_output_packets_total", m_tshark_packets},
			{"processed_packets_total", m_processed_packets},
			{"rate_interval_sec", first ? json(nullptr) : json(elapsed)},
			{"tshark_output_packets_per_sec", !first && elapsed > 0.0 ? json((m_tshark_packets - previous_tshark) / elapsed) : json(nullptr)},
			{"processed_packets_per_sec", !first && elapsed > 0.0 ? json((m_processed_packets - previous_processed) / elapsed) : json(nullptr)},
		};
		previous = now;
		previous_tshark = m_tshark_packets;
		previous_processed = m_processed_packets;
		first = false;
		const bool finished = stop.stop_requested();
		lock.unlock();
		const bool written = write_snapshot(snapshot);
		if(!written && !write_failed) trace(0, "warn: failed to write pipeline progress %s", m_cfg.output_file.string().c_str());
		write_failed = !written;
		if(finished) break;
		lock.lock();
	}
}

bool pipeline_progress::write_snapshot(const json &snapshot) const {
	std::error_code error;
	const auto parent = m_cfg.output_file.parent_path();
	if(!parent.empty()) std::filesystem::create_directories(parent, error);
	if(error) return false;
	const auto temporary = m_cfg.output_file.string() + "." + std::to_string(getpid()) + ".tmp";
	{
		std::ofstream out(temporary, std::ios::trunc);
		if(!out) return false;
		out << snapshot.dump() << '\n';
		out.close();
		if(!out) {
			std::filesystem::remove(temporary, error);
			return false;
		}
	}
	std::filesystem::rename(temporary, m_cfg.output_file, error);
	if(!error) return true;
	std::filesystem::remove(temporary, error);
	return false;
}
