bool is_lifetime_timeline_event(const event_record &e) {
	return e.type == "stream_detected" || e.type == "stream_lost" ||
	       e.type == "flow_detected" || e.type == "flow_lost";
}

int emit_reclassified_timeline_rows(timeline_sink &timeline, const event_record &e) {
	if(!e.detail.is_object()) return 0;
	const auto from = e.detail.value("from", json::object());
	if(!from.is_object()) return 0;
	int rc = 0;
	auto emit_entries = [&](const char *field, const char *kind, const char *subject_type) {
		const auto entries = from.value(field, json::array());
		if(!entries.is_array()) return;
		for(const auto &entry : entries) {
			if(!entry.is_object()) continue;
			json subject = entry.value("source", json::object());
			if(!subject.is_object()) continue;
			subject["type"] = subject_type;
			json detail = entry.value("detail", json::object());
			if(!detail.is_object()) detail = json::object();
			detail["event_type"] = e.type;
			detail["to_proto"] = e.detail.value("to", json::object()).value("proto", std::string{});
			const int current = timeline.emit(e.time_epoch, kind, std::move(subject), std::move(detail));
			if(rc == 0 && current != 0) rc = current;
		}
	};
	emit_entries("flows", "flow_reclassified", "flow");
	emit_entries("streams", "stream_reclassified", "stream");
	return rc;
}

bool ends_with(const std::string &value, const std::string &suffix) {
	return value.size() >= suffix.size() &&
	       value.compare(value.size() - suffix.size(), suffix.size(), suffix) == 0;
}

bool is_timeline_marker_event(const event_record &e) {
	if(e.type == "alert_detected" || e.type == "alert_recovered" || e.type == "alert_data_unavailable" || e.type == "alert_data_available") {
		return true;
	}
	if(e.type.rfind("stream_", 0) == 0 || e.type.rfind("flow_", 0) == 0) {
		return false;
	}
	return ends_with(e.type, "_occurred") || ends_with(e.type, "_recovered");
}

std::string marker_action(const std::string &type) {
	if(type == "alert_data_unavailable") return "unavailable";
	if(type == "alert_data_available") return "available";
	if(ends_with(type, "_detected") || ends_with(type, "_occurred")) return "detected";
	if(ends_with(type, "_recovered")) return "recovered";
	return "event";
}

json make_marker_subject(const event_record &e) {
	json subject = e.source.is_object() ? e.source : json::object();
	if(!subject.contains("type")) {
		if(subject.contains("target") && subject["target"].is_string()) {
			subject["type"] = subject["target"];
		}
		else if(subject.contains("flow_key")) {
			subject["type"] = "flow";
		}
		else if(subject.contains("stream_key")) {
			subject["type"] = "stream";
		}
		else if(subject.contains("interface_id") || subject.contains("name")) {
			subject["type"] = "interface";
		}
	}
	return subject;
}

json make_marker_detail(const event_record &e) {
	json detail = e.detail.is_object() ? e.detail : json::object();
	detail["event_type"] = e.type;
	detail["action"] = marker_action(e.type);
	if(e.source.is_object()) {
		for(const auto &key : {"alert_id", "severity", "target", "proto", "stream_key", "flow_key", "interface_id", "name"}) {
			if(e.source.contains(key) && !detail.contains(key)) detail[key] = e.source[key];
		}
	}
	if(!detail.contains("label")) {
		if(detail.contains("alert_id") && detail["alert_id"].is_string()) detail["label"] = detail["alert_id"];
		else if(detail.contains("metric") && detail["metric"].is_string()) detail["label"] = detail["metric"];
		else detail["label"] = e.type;
	}
	if(!detail.contains("severity")) {
		detail["severity"] = (e.type == "alert_detected" || e.type == "alert_data_unavailable") ? "warning" : "info";
	}
	return detail;
}

