import { getPlaybackStatus } from "../api/client";
import type { AnalysisSource, SourcePresentation } from "../analysisSource";
import { createDataClock } from "../dataClock";
import { playbackTime, type PlaybackStatus } from "../playbackClock";

// This adapter discovers both live and journal-replay servers using the
// existing protocol. A future file-analysis adapter can implement the same contract.
export function createPlaybackSource(
  readStatus: (timeoutMs?: number) => Promise<PlaybackStatus | null> = getPlaybackStatus,
  clock = createDataClock()
): AnalysisSource {
  let status: PlaybackStatus | null = null;
  const update = (next: PlaybackStatus | null) => {
    status = next;
    clock.setTime(playbackTime(next));
  };
  return {
    nowSec: () => clock.nowSec(),
    presentation(): SourcePresentation {
      if (!status) return { advancing: true, badge: null };
      const details: string[] = [];
      if (status.loop) details.push(` · LOOP ${status.cycle + 1}`);
      if (status.mode === "original") details.push(` · ${new Date(status.now * 1000).toLocaleString()}`);
      return {
        advancing: status.state === "playing",
        badge: { className: "playback-badge", ariaLabel: "Replay mode",
          text: `REPLAY ${status.mode.toUpperCase()} · ${status.speed}× · ${status.state}`, details }
      };
    },
    async refresh(timeoutMs) { update(await readStatus(timeoutMs)); },
    handleMessage(message) {
      if (message.type !== "playback:status") return false;
      update(message.playback);
      return true;
    }
  };
}
