		{"pending_topology", {
			{"dirty", m_topology_dirty},
			{"time", m_pending_topology_time},
			{"source", m_pending_topology_source},
		}},
	}.dump() << '\n';
	output.flush();
	output.close();
	if(!output) {
		trace(0, "projector: state write failed: %s", temporary.c_str());
		return false;
	}
	std::error_code ec{};
	std::filesystem::rename(temporary, m_cfg.state_file, ec);
