		}},
	}.dump() << '\n';
	output.flush();
	output.close();
	if(!output) {
		trace(0, "projector: state write failed: %s", temporary.c_str());
		return false;
	}
	std::error_code ec{};
	std::filesystem::rename(temporary, m_cfg.state_file, ec);
	if(ec) trace(0, "projector: state replace failed: %s", ec.message().c_str());
	return !ec;
}

