#!/usr/bin/env python3
"""Isolated PCAP analysis jobs. No live service or original capture is modified."""
import argparse
import collections
import datetime as dt
import fcntl
import hashlib
import json
import math
import os
from pathlib import Path
import re
import shutil
import signal
import struct
import subprocess
import sys
import threading
import time

PROJECT = Path(__file__).resolve().parent.parent
TERMINAL = {'completed', 'failed', 'interrupted'}


def read_json(path, default=None):
    try:
        return json.loads(Path(path).read_text())
    except (FileNotFoundError, json.JSONDecodeError):
        return default


def atomic_json(path, value):
    path = Path(path)
    tmp = path.with_name(path.name + f'.{os.getpid()}.tmp')
    with tmp.open('w') as out:
        json.dump(value, out, allow_nan=False, indent=2)
        out.write('\n')
    tmp.replace(path)


def timestamp(value):
    try:
        parsed = dt.datetime.fromisoformat(value.replace('Z', '+00:00'))
        if parsed.tzinfo is None:
            raise ValueError('timezone offset is required')
        result = parsed.timestamp()
        if not math.isfinite(result) or result <= 0:
            raise ValueError('timestamp must be positive')
        return result
    except ValueError as exc:
        raise argparse.ArgumentTypeError(f'invalid ISO8601 time {value}: {exc}') from exc


def duration(value):
    match = re.fullmatch(r'(\d+(?:\.\d+)?)(ms|s|m|h|d)?', value)
    if not match:
        raise argparse.ArgumentTypeError('duration must be NUMBER[ms|s|m|h|d]')
    result = float(match[1]) * {'ms': .001, 's': 1, 'm': 60, 'h': 3600, 'd': 86400, None: 1}[match[2]]
    if not math.isfinite(result) or result <= 0:
        raise argparse.ArgumentTypeError('duration must be positive and finite')
    return result


def positive(value):
    result = float(value)
    if not math.isfinite(result) or result <= 0:
        raise argparse.ArgumentTypeError('value must be positive and finite')
    return result


def blocks(path):
    """Strict subset accepted by pcap_streamer; never invent missing timestamps."""
    with Path(path).open('rb') as source:
        first = True
        while header := source.read(8):
            if len(header) != 8:
                raise ValueError(f'truncated block header: {path}')
            kind, size = struct.unpack('<II', header)
            if size < 12 or size % 4 or size > 256 * 1024 * 1024:
                raise ValueError(f'invalid/unsupported little-endian pcapng block: {path}')
            rest = source.read(size - 8)
            if len(rest) != size - 8 or struct.unpack('<I', rest[-4:])[0] != size:
                raise ValueError(f'truncated/invalid block: {path}')
            if first and (kind != 0x0a0d0d0a or size < 28 or rest[:4] != b'\x4d\x3c\x2b\x1a'):
                raise ValueError(f'expected little-endian PCAPNG: {path}')
            if not first and kind == 0x0a0d0d0a:
                raise ValueError(f'multiple PCAPNG sections are unsupported: {path}')
            first = False
            yield kind, header + rest
        if first:
            raise ValueError(f'empty PCAPNG: {path}')


def inspect_pcap(path):
    interfaces, clocks, times = [], [], []
    digest = hashlib.sha256()
    packets = 0
    low = high = None
    seen_packet = False
    for kind, block in blocks(path):
        digest.update(block)
        if kind == 1:
            if seen_packet or len(block) < 20:
                raise ValueError(f'invalid interface block: {path}')
            interfaces.append(block.hex())
            resolution, offset = 1e-6, 0
            pos = 16
            while pos < len(block) - 4:
                if pos + 4 > len(block) - 4:
                    raise ValueError(f'truncated interface option: {path}')
                code, length = struct.unpack_from('<HH', block, pos)
                pos += 4
                if pos + length > len(block) - 4:
                    raise ValueError(f'truncated interface option: {path}')
                value = block[pos:pos + length]
                if code == 0:
                    if length != 0:
                        raise ValueError(f'invalid end option: {path}')
                    break
                if code == 9:
                    if length != 1:
                        raise ValueError(f'invalid timestamp resolution: {path}')
                    resolution = (2.0 ** -(value[0] & 127)) if value[0] & 128 else 10.0 ** -value[0]
                if code == 14:
                    if length != 8:
                        raise ValueError(f'invalid timestamp offset: {path}')
                    offset = struct.unpack('<q', value)[0]
                pos += (length + 3) & ~3
            clocks.append((resolution, offset))
        elif kind == 6:
            seen_packet = True
            if len(block) < 32:
                raise ValueError(f'invalid packet block: {path}')
            interface, hi, lo, captured, original = struct.unpack_from('<IIIII', block, 8)
            if interface >= len(clocks) or captured > original or 32 + ((captured + 3) & ~3) > len(block):
                raise ValueError(f'invalid packet/interface length: {path}')
            resolution, offset = clocks[interface]
            when = ((hi << 32) | lo) * resolution + offset
            if not math.isfinite(when) or when <= 0:
                raise ValueError(f'invalid packet timestamp: {path}')
            low = when if low is None else min(low, when)
            high = when if high is None else max(high, when)
            packets += 1
        elif kind in (2, 3):
            raise ValueError(f'packet blocks without supported timestamps: {path}')
    if not interfaces:
        raise ValueError(f'PCAPNG has no interfaces: {path}')
    return {'first': low, 'last': high, 'packets': packets, 'interfaces': interfaces,
            'sha256': digest.hexdigest(), 'size': Path(path).stat().st_size}


def safe_root(value):
    root = Path(value).expanduser().resolve()
    if root == Path('/'):
        raise ValueError('output cannot be /')
    return root


def disjoint(a, b):
    return a != b and a not in b.parents and b not in a.parents


def initial_state(manifest):
    return {'enabled': True, 'schema_version': 1, 'kind': 'file', 'state': 'ready',
            'pace': manifest['pace'], 'speed': manifest['speed'], 'range': manifest['range'],
            'now': manifest['range']['actualFrom'], 'progress': {'consumedFiles': 0,
            'totalFiles': len(manifest['files']), 'processedPackets': 0},
            'projection': 'pending', 'error': None, 'warnings': manifest['warnings']}


def snapshot_configs(args, root):
    config_file = Path(args.config).resolve()
    config = read_json(config_file)
    if not isinstance(config, dict):
        raise ValueError(f'invalid STM config: {config_file}')
    config = json.loads(json.dumps(config))
    refs = config.pop('configs', {})
    if config.get('stm'):
        raise ValueError('legacy stm config overlay is unsupported for jobs; use top-level input/logs/configs')
    config['configs'] = {}
    for field, aliases in {'tshark': ['tshark', 'tshark_config'], 'protocol_map': ['protocol_map'],
                           'alerts': ['alerts', 'alert_config']}.items():
        ref = next((refs[key] for key in aliases if refs.get(key)), None)
        if ref:
            source = Path(ref)
            if not source.is_absolute():
                source = config_file.parent / source
            data = read_json(source)
            if data is None:
                raise ValueError(f'invalid referenced config: {source}')
            destination = root / 'config' / f'{field}.json'
            atomic_json(destination, data)
            config['configs'][field] = str(destination)
    if args.tshark:
        if 'tshark' in config['configs']:
            file = Path(config['configs']['tshark'])
            data = read_json(file)
            data.get('tshark', data)['program'] = args.tshark
            atomic_json(file, data)
        else:
            config.setdefault('tshark', {})['program'] = args.tshark
    config['logs'] = {'dir': str(root / 'result'), 'event_journal_dir': 'event-journal',
                      'metrics_journal_dir': 'metrics-journal', 'journal_retention_hours': 0}
    # Capture is descriptive only. No dumpcap, healthd, storage-manager or live broker runs.
    config.setdefault('capture', {})['output'] = str(root / 'capture' / 'cap.pcapng')
    config['capture']['ring_files'] = args.ring_files
    config['capture_health'] = {'enabled': False,
                               'pipeline_status_file': str(root / 'pipeline-status.json'),
                               'pipeline_progress_file': str(root / 'pipeline-progress.json')}
    config['storage'] = {'enabled': False}
    config['projector'] = {'output_dir': str(root / 'result' / 'derived'), 'retention_hours': 0,
                           'inactive_retention_sec': 0}
    return config


def prepare(args, root):
    if args.to is not None and args.duration is not None:
        raise ValueError('--to and --duration are mutually exclusive')
    if args.ring_files < 1:
        raise ValueError('--ring-files must be at least 1')
    if args.pre_roll < 0 or not math.isfinite(args.pre_roll):
        raise ValueError('--pre-roll must be nonnegative seconds')
    source = Path(args.source).resolve()
    if not source.is_dir() or not disjoint(source, root):
        raise ValueError('source and output must be separate directories, neither inside the other')
    # mkdir is exclusive: a stale, partially prepared or completed job is never reused.
    root.mkdir(parents=True, exist_ok=False)
    atomic_json(root / 'analysis-state.json', {'enabled': True, 'schema_version': 1,
                'kind': 'file', 'state': 'preparing'})
    try:
        for name in ('input', 'capture', 'result', 'runtime', 'fe-state', 'config'):
            (root / name).mkdir()
        config = snapshot_configs(args, root)
        files = sorted(p for p in source.rglob('*') if not p.is_symlink() and p.is_file()
                       and p.suffix.lower() in ('.pcap', '.pcapng'))
        metadata = []
        warnings = []
        seen = {}
        for file in files:
            info = inspect_pcap(file)
            if info['packets'] == 0:
                warnings.append(f'empty capture omitted (close time unavailable): {file}')
                continue
            if info['sha256'] in seen:
                warnings.append(f'duplicate capture omitted: {file} == {seen[info["sha256"]]}')
                continue
            seen[info['sha256']] = str(file)
            metadata.append((file, info))
        metadata.sort(key=lambda item: (item[1]['first'], item[1]['last'], str(item[0])))
        if not metadata:
            raise ValueError('no timestamped packets found')
        first = min(info['first'] for _, info in metadata)
        last = max(info['last'] for _, info in metadata)
        start = first if args.start is None else args.start
        end = start + args.duration if args.duration is not None else args.to
        if end is not None and end <= start:
            raise ValueError('end must be later than start')
        # Inspect timestamps, not just file extents: a requested interval may contain only a gap.
        selected = [(file, info) for file, info in metadata
                    if info['last'] >= start - args.pre_roll and (end is None or info['first'] < end)]
        selected_times = []
        for file, _ in selected:
            for kind, block in blocks(file):
                if kind == 1:
                    pass
            # Exact range presence is checked by the same timestamp-aware scan below.
        reference = selected[0][1]['interfaces'] if selected else None
        entries = []
        actual_low = actual_high = None
        for index, (file, info) in enumerate(selected):
            if info['interfaces'] != reference:
                raise ValueError(f'interface definitions changed: {file}')
            target = root / 'input' / f'cap_{index:08d}.pcapng'
            shutil.copyfile(file, target)
            secured = inspect_pcap(target)
            if secured['sha256'] != info['sha256']:
                raise ValueError(f'input changed while securing: {file}')
            # Enumerate packet times for exact [A,B) bounds and collect no payload in memory.
            for when in packet_times(target):
                if when >= start and (end is None or when < end):
                    actual_low = when if actual_low is None else min(actual_low, when)
                    actual_high = when if actual_high is None else max(actual_high, when)
            if entries and info['first'] - entries[-1]['last'] > args.gap_threshold:
                warnings.append(f'possible capture gap: {entries[-1]["last"]} .. {info["first"]} (traffic silence is also possible)')
            entries.append({'path': str(target), 'name': target.name, 'source': str(file),
                            **{key: info[key] for key in ('first', 'last', 'packets', 'sha256', 'size')},
                            'publishTime': info['last'], 'publishTimeBasis': 'last-packet-estimate'})
        if actual_low is None:
            raise ValueError('no packets in requested time range')
        if start < first:
            warnings.append('requested start precedes available capture')
        if start - args.pre_roll < first and args.pre_roll:
            warnings.append('pre-roll is shorter than requested')
        if end is not None and end > last:
            warnings.append('capture ends before requested end')
        # Out-of-order packet extents must not make scheduled publication run backwards.
        watermark = entries[0]['publishTime']
        for item in entries:
            if item['publishTime'] < watermark:
                warnings.append(f'overlapping capture time clamped for scheduling: {item["source"]}')
            watermark = max(watermark, item['publishTime'])
            item['publishTime'] = watermark
        manifest = {'schema_version': 1, 'source': str(source), 'pace': args.pace,
                    'speed': args.speed, 'ringFiles': args.ring_files, 'preRoll': args.pre_roll,
                    'range': {'from': start, 'to': end, 'actualFrom': actual_low, 'actualTo': actual_high},
                    'warnings': warnings, 'files': entries,
                    'timingBasis': 'last packet timestamp per file; original close times unavailable'}
        config['input'] = {'processing_mode': 'continuous', 'analysis_from': start,
                           'receipt_file': str(root / 'input-status.json')}
        if end is not None:
            config['input']['analysis_to'] = end
        if args.pace == 'full':
            config['input']['manifest'] = str(root / 'manifest.json')
        else:
            config['input'].update({'watch_dir': str(root / 'capture'), 'pcap_prefix': 'cap_',
                'completion_file': str(root / 'supply-done.json'),
                'ready_file': str(root / 'watch-ready.json'), 'ring_files': args.ring_files})
        atomic_json(root / 'manifest.json', manifest)
        atomic_json(root / 'config' / 'stm_config.json', config)
        job = {'binDir': str(Path(args.bin_dir).resolve()), 'feDir': str(Path(args.fe_dir).resolve()),
               'node': shutil.which(args.node) or args.node, 'host': args.host, 'port': args.port,
               'drainTimeout': args.drain_timeout, 'script': str(Path(__file__).resolve()),
               'python': sys.executable}
        atomic_json(root / 'job.json', job)
        atomic_json(root / 'analysis-state.json', initial_state(manifest))
        return manifest
    except BaseException as exc:
        atomic_json(root / 'analysis-state.json', {'enabled': True, 'schema_version': 1,
                    'kind': 'file', 'state': 'failed', 'error': str(exc)})
        raise


def packet_times(path):
    clocks = []
    for kind, block in blocks(path):
        if kind == 1:
            resolution, offset = 1e-6, 0
            pos = 16
            while pos + 4 <= len(block) - 4:
                code, length = struct.unpack_from('<HH', block, pos)
                pos += 4
                if code == 0:
                    break
                if code == 9:
                    val = block[pos]
                    resolution = 2.0 ** -(val & 127) if val & 128 else 10.0 ** -val
                if code == 14:
                    offset = struct.unpack_from('<q', block, pos)[0]
                pos += (length + 3) & ~3
            clocks.append((resolution, offset))
        if kind == 6:
            interface, hi, lo = struct.unpack_from('<III', block, 8)
            resolution, offset = clocks[interface]
            yield ((hi << 32) | lo) * resolution + offset


def record_event(root, event, **detail):
    with (root / 'supply-events.ndjson').open('a') as out:
        out.write(json.dumps({'event': event, 'wall': time.time(), 'monotonic': time.monotonic(), **detail}) + '\n')


def produce(root):
    manifest = read_json(root / 'manifest.json')
    stopped = threading.Event()
    for sig in (signal.SIGINT, signal.SIGTERM):
        signal.signal(sig, lambda *_: stopped.set())
    origin = time.monotonic()
    first = manifest['files'][0]['publishTime']
    ring = collections.deque()
    for item in manifest['files']:
        deadline = origin + (item['publishTime'] - first) / manifest['speed']
        if stopped.wait(max(0, deadline - time.monotonic())):
            return 130
        # The producer never reads STM progress, receipts or its input pipe.
        while len(ring) >= manifest['ringFiles']:
            old = ring.popleft()
            old.unlink()
            record_event(root, 'delete', name=old.name)
        target = root / 'capture' / item['name']
        # Close the final watched path: atomic rename alone would not emit CLOSE_WRITE.
        shutil.copyfile(item['path'], target)
        ring.append(target)
        record_event(root, 'close', name=target.name, recordTime=item['publishTime'],
                     latenessSec=max(0, time.monotonic() - deadline))
    atomic_json(root / 'supply-done.json', {'schema_version': 1,
                'files': [item['name'] for item in manifest['files']]})
    record_event(root, 'done')
    return 0


def stop_child(child):
    if child is None:
        return
    # Kill the owned session even if its direct parent has already exited.
    try:
        os.killpg(child.pid, signal.SIGTERM)
    except ProcessLookupError:
        pass
    try:
        child.wait(timeout=5)
    except subprocess.TimeoutExpired:
        pass
    try:
        os.killpg(child.pid, signal.SIGKILL)
    except ProcessLookupError:
        pass
    child.wait(timeout=5)


def refresh_progress(root, state):
    progress = read_json(root / 'pipeline-progress.json', {})
    receipt = read_json(root / 'input-status.json', {})
    state['progress'].update({'consumedFiles': receipt.get('consumed_files', 0),
                             'processedPackets': progress.get('processed_packets_total', 0),
                             'tsharkPackets': progress.get('tshark_output_packets_total', 0)})
    now = progress.get('last_processed_packet_time')
    if isinstance(now, (float, int)) and math.isfinite(now):
        state['now'] = max(state['range']['actualFrom'], min(now, state['range']['actualTo']))
    atomic_json(root / 'analysis-state.json', state)


def work(root):
    with (root / 'runtime' / 'worker.lock').open('w') as lock:
        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        state = read_json(root / 'analysis-state.json')
        if not state or state['state'] != 'ready':
            raise ValueError('job must be prepared and ready; use a new output for another run')
        job = read_json(root / 'job.json')
        stopped = threading.Event()
        for sig in (signal.SIGINT, signal.SIGTERM):
            signal.signal(sig, lambda *_: stopped.set())
        state['state'] = 'running'
        atomic_json(root / 'analysis-state.json', state)
        stm = producer = None
        try:
            with (root / 'runtime' / 'stm.log').open('ab') as log:
                env = {**os.environ, 'STM_LOG_LEVEL_FILE': str(root / 'runtime' / 'log-levels.json')}
                stm = subprocess.Popen([str(Path(job['binDir']) / 'stm'), '--config',
                    str(root / 'config' / 'stm_config.json')], stdout=log, stderr=log,
                    cwd=root, env=env, start_new_session=True)
                state['pid'] = stm.pid
                if state['pace'] == 'recorded':
                    deadline = time.monotonic() + 15
                    while not (root / 'watch-ready.json').exists():
                        if stopped.wait(.02):
                            raise InterruptedError('analysis interrupted')
                        if stm.poll() is not None:
                            raise RuntimeError(f'STM exited before watcher ready: {stm.returncode}')
                        if time.monotonic() >= deadline:
                            raise TimeoutError('watcher readiness timed out')
                    producer = subprocess.Popen([sys.executable, str(Path(__file__).resolve()),
                        '_produce', '--output', str(root)], stdout=log, stderr=log,
                        cwd=root, start_new_session=True)
                drain_deadline = None
                while stm.poll() is None:
                    if stopped.wait(.1):
                        raise InterruptedError('analysis interrupted')
                    if producer and producer.poll() not in (None, 0):
                        raise RuntimeError(f'PCAP producer failed: {producer.returncode}')
                    receipt = read_json(root / 'input-status.json', {})
                    supply_done = producer is not None and producer.poll() == 0
                    if (receipt.get('input_complete') or supply_done) and drain_deadline is None:
                        state['state'] = 'draining'
                        drain_deadline = time.monotonic() + job['drainTimeout']
                    if drain_deadline is not None and time.monotonic() > drain_deadline:
                        raise TimeoutError('STM/tshark drain timed out')
                    refresh_progress(root, state)
                if stopped.is_set():
                    raise InterruptedError('analysis interrupted')
                if stm.returncode != 0:
                    raise RuntimeError(f'STM exited with code {stm.returncode}; see runtime/stm.log')
                if producer:
                    producer.wait(timeout=5)
                    if producer.returncode != 0:
                        raise RuntimeError(f'PCAP producer failed: {producer.returncode}')
                state['state'] = 'completed'
                state['exitCode'] = 0
                state['now'] = state['range']['actualTo']
                return 0
        except InterruptedError as exc:
            state.update(state='interrupted', error=str(exc), exitCode=130)
            return 130
        except Exception as exc:
            state.update(state='failed', error=str(exc), exitCode=1)
            return 1
        finally:
            stop_child(producer)
            stop_child(stm)
            state.pop('pid', None)
            refresh_progress(root, state)


def journal_tail(root):
    result = {}
    for name in ('event', 'metrics'):
        directory = root / 'result' / f'{name}-journal'
        files = list(directory.rglob('*.ndjson'))
        def order(file):
            match = re.fullmatch(r'(\d{2})(?:\.part(\d+))?\.ndjson', file.name)
            return str(file.parent), match[1] if match else file.name, int(match[2] or 0) if match else 0
        files.sort(key=order)
        result[f'{name}_cursor'] = None if not files else {
            'path': str(files[-1].relative_to(directory)), 'offset': files[-1].stat().st_size}
    return result


def projection_ready(root):
    cursor = read_json(root / 'result' / 'derived' / 'projector-state.json', {})
    tail = journal_tail(root)
    return all(value is None or all(cursor.get(key, {}).get(field) == expected for field, expected in value.items())
               for key, value in tail.items()) and not cursor.get('pending_topology', {}).get('dirty', False)


def supervisor_env(root, job):
    env = {**os.environ, 'STM_ANALYSIS_ROOT': str(root), 'STM_ANALYSIS_SCRIPT': job['script'],
           'STM_ANALYSIS_PYTHON': job['python'], 'STM_ANALYSIS_BIN': job['binDir'],
           'STM_ANALYSIS_FE': job['feDir'], 'STM_ANALYSIS_NODE': job['node'],
           'STM_ANALYSIS_HOST': job['host'], 'STM_ANALYSIS_PORT': str(job['port'])}
    for key in [key for key in env if key.startswith('STM_ANALYSIS_')]:
        if not re.fullmatch(r'[A-Za-z0-9_./:-]+', env[key]):
            raise ValueError(f'{key}: Supervisor values must not contain spaces or special characters')
    return env


def ctl(root, job, *command, check=True):
    return subprocess.run(['supervisorctl', '-c', str(PROJECT / 'docker' / 'supervisord.analysis.conf'),
                           *command], env=supervisor_env(root, job), capture_output=True, text=True,
                           check=check, timeout=50)


def services(root, action):
    job = read_json(root / 'job.json')
    if not job:
        raise ValueError('job.json is missing; prepare the job first')
    if action == 'up':
        if read_json(root / 'analysis-state.json', {}).get('state') != 'ready':
            raise ValueError('job must be ready; use a new output to rerun')
        for file in (Path(job['binDir']) / 'stm', Path(job['binDir']) / 'stm_projector',
                     Path(job['feDir']) / 'server' / 'dist' / 'index.js',
                     Path(job['feDir']) / 'client' / 'dist' / 'index.html'):
            if not file.is_file():
                raise ValueError(f'build required: {file}')
        if len(str(root / 'runtime' / 'supervisor.sock').encode()) > 100:
            raise ValueError('output path too long for Supervisor Unix socket')
        if (root / 'runtime' / 'supervisor.sock').exists() or (root / 'runtime' / 'supervisord.pid').exists():
            raise ValueError('Supervisor runtime already exists; inspect status/shutdown first')
        subprocess.run(['supervisord', '-c', str(PROJECT / 'docker' / 'supervisord.analysis.conf')],
                       env=supervisor_env(root, job), check=True)
        try:
            for name in ('projector', 'frontend', 'analysis'):
                result = ctl(root, job, 'start', name)
                print(result.stdout.strip())
        except Exception:
            ctl(root, job, 'stop', 'all', check=False)
            ctl(root, job, 'shutdown', check=False)
            raise
        print(f'http://{job["host"]}:{job["port"]} (analysis EOF leaves projector and FE running)')
    elif action == 'stop':
        result = ctl(root, job, 'stop', 'analysis', check=False)
        if result.returncode not in (0, 1) or (result.returncode and 'not running' not in result.stdout):
            raise RuntimeError(result.stdout + result.stderr)
    elif action == 'shutdown':
        ctl(root, job, 'stop', 'all')
        ctl(root, job, 'shutdown')
        deadline = time.monotonic() + 15
        while (root / 'runtime' / 'supervisor.sock').exists() or (root / 'runtime' / 'supervisord.pid').exists():
            if time.monotonic() > deadline:
                raise TimeoutError('Supervisor shutdown timed out')
            time.sleep(.1)
    else:
        print(json.dumps(read_json(root / 'analysis-state.json'), indent=2))
        print(f'projection: {"ready" if projection_ready(root) else "pending"}')
        if (root / 'runtime' / 'supervisor.sock').exists():
            print(ctl(root, job, 'status', check=False).stdout)


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('action', choices=['prepare', 'run', 'up', 'status', 'stop', 'shutdown', '_work', '_produce'])
    parser.add_argument('--output', required=True)
    parser.add_argument('--source')
    parser.add_argument('--config', default=str(PROJECT / 'conf' / 'stm_config.json'))
    parser.add_argument('--from', dest='start', type=timestamp)
    parser.add_argument('--to', type=timestamp)
    parser.add_argument('--duration', type=duration)
    parser.add_argument('--pre-roll', type=float, default=0, help='tshark reassembly pre-roll in recorded seconds')
    parser.add_argument('--pace', choices=['full', 'recorded'], default='full')
    parser.add_argument('--speed', type=positive, default=1)
    parser.add_argument('--ring-files', type=int, default=60)
    parser.add_argument('--gap-threshold', type=positive, default=2)
    parser.add_argument('--drain-timeout', type=positive, default=120)
    parser.add_argument('--bin-dir', default=os.environ.get('STM_BIN_DIR', str(PROJECT / 'be' / 'build')))
    parser.add_argument('--fe-dir', default=os.environ.get('STM_FE_DIR', str(PROJECT / 'fe')))
    parser.add_argument('--node', default=os.environ.get('STM_NODE_BIN', 'node'))
    parser.add_argument('--tshark', help='override tshark executable in the job config snapshot')
    parser.add_argument('--host', default='127.0.0.1')
    parser.add_argument('--port', type=int, default=3200)
    args = parser.parse_args(argv)
    try:
        root = safe_root(args.output)
        if not 1 <= args.port <= 65535:
            raise ValueError('port must be 1..65535')
        if args.action in ('prepare', 'run', 'up') and args.source:
            prepare(args, root)
        elif args.action == 'prepare':
            raise ValueError('--source is required for prepare')
        if args.action == 'prepare':
            print(f'prepared: {root / "manifest.json"}')
            return 0
        if args.action in ('run', '_work'):
            return work(root)
        if args.action == '_produce':
            return produce(root)
        services(root, args.action)
        return 0
    except (OSError, ValueError, RuntimeError, subprocess.SubprocessError) as exc:
        print(f'file analysis: {exc}', file=sys.stderr)
        return 1


if __name__ == '__main__':
    sys.exit(main())
