import { readFileSync, readdirSync, statSync } from "node:fs";
import path from "node:path";
import type { AnalysisSource } from "./analysisSource";
import type { FileAnalysisStatus } from "../shared/analysisSourceProtocol";

const states = new Set(["ready", "running", "draining", "completed", "failed", "interrupted"]);
export function isFileAnalysisStatus(value: unknown): value is FileAnalysisStatus {
  if (!value || typeof value !== "object") return false;
  const s = value as FileAnalysisStatus;
  const finite = (n: unknown) => typeof n === "number" && Number.isFinite(n);
  return s.enabled === true && s.schema_version === 1 && s.kind === "file" && states.has(s.state) &&
    ["full", "recorded"].includes(s.pace) && finite(s.speed) && s.speed > 0 && finite(s.now) &&
    !!s.range && finite(s.range.from) && (s.range.to === null || finite(s.range.to)) &&
    finite(s.range.actualFrom) && finite(s.range.actualTo) && s.range.actualFrom <= s.range.actualTo &&
    !!s.progress && [s.progress.consumedFiles, s.progress.totalFiles, s.progress.processedPackets].every(n => Number.isSafeInteger(n) && n >= 0) &&
    ["pending", "ready"].includes(s.projection) && (s.error === null || typeof s.error === "string") &&
    Array.isArray(s.warnings) && s.warnings.every(w => typeof w === "string");
}

function journalFiles(root: string): string[] {
  try {
    return readdirSync(root, { withFileTypes: true }).flatMap(entry => {
      const file = path.join(root, entry.name);
      return entry.isDirectory() ? journalFiles(file) : entry.isFile() && entry.name.endsWith(".ndjson") ? [file] : [];
    });
  } catch { return []; }
}

// Mirrors journal_reader's numeric part order, rather than lexical part10 < part2.
function journalOrder(a: string, b: string): number {
  const key = (file: string) => { const m = /^(\d{2})(?:\.part(\d+))?\.ndjson$/.exec(path.basename(file));
    return { base: path.join(path.dirname(file), m?.[1] ?? path.basename(file)), part: Number(m?.[2] ?? 0) }; };
  const x = key(a), y = key(b);
  return x.base < y.base ? -1 : x.base > y.base ? 1 : x.part - y.part;
}

export function projectionReady(logDir: string): boolean {
  try {
    const cursor = JSON.parse(readFileSync(path.join(logDir, "derived/projector-state.json"), "utf8"));
    for (const name of ["event", "metrics"]) {
      const root = path.join(logDir, `${name}-journal`);
      const last = journalFiles(root).sort(journalOrder).at(-1);
      if (!last) continue;
      const position = cursor[`${name}_cursor`];
      if (position?.path !== path.relative(root, last) || position?.offset !== statSync(last).size) return false;
    }
    return !cursor.pending_topology?.dirty;
  } catch { return false; }
}

export function createFileAnalysisSource(stateFile: string, logDir?: string): AnalysisSource {
  let lastNow = 0;
  let projected = false, checkedAt = 0;
  const status = (): FileAnalysisStatus | null => {
    try {
      const state: unknown = JSON.parse(readFileSync(stateFile, "utf8"));
      if (!isFileAnalysisStatus(state)) return null;
      lastNow = Math.max(state.range.actualFrom, Math.min(state.now, state.range.actualTo));
      if (logDir && Date.now() - checkedAt >= 500) {
        projected = projectionReady(logDir); checkedAt = Date.now();
      }
      return { ...state, now: lastNow, projection: projected ? "ready" : "pending" };
    } catch { return null; }
  };
  return {
    runtimeControlEnabled: false,
    runtimeMutationError: "settings and process operations are disabled during file analysis",
    nowSec() { status(); return lastNow; },
    registerRoutes(app) {
      app.get("/api/playback", async () => ({ enabled: false }));
      app.get("/api/analysis", async (_request, reply) => {
        const current = status();
        return current ?? reply.code(503).send({ error: "analysis state is unavailable" });
      });
    },
    statusMessages() { const current = status(); return current ? [{ type: "analysis:status", analysis: current }] : []; }
  };
}
