async function availablePort() {
  const server = net.createServer();
  await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
  const port = server.address().port;
  await new Promise((resolve) => server.close(resolve));
  return port;
}

async function waitFor(url, child) {
  for (let attempt = 0; attempt < 100; attempt += 1) {
    if (child.exitCode !== null) throw new Error(`server exited ${child.exitCode}`);
    try {
      const response = await fetch(url);
      if (response.ok) return response;
    } catch { /* Server is still starting. */ }
    await new Promise((resolve) => setTimeout(resolve, 50));
  }
  throw new Error("server did not start");
}

test("parallel live and recorded servers isolate time and live process control", { skip: !fs.existsSync(serverEntry) }, async () => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "stm-source-api-"));
  const children = [];
  const brokerPath = path.join(root, "control.sock");
  let connections = 0;
  const broker = net.createServer(socket => {
    connections += 1;
    socket.once("data", () => socket.end(JSON.stringify({ ok: true, processes: [] }) + "\n"));
  });
  try {
    await new Promise((resolve, reject) => { broker.once("error", reject); broker.listen(brokerPath, resolve); });
    const urls = {};
    const recordedTime = 1609459200;
    for (const name of ["live", "recorded"]) {
      const dir = path.join(root, name); fs.mkdirSync(dir);
      if (name === "recorded") fs.writeFileSync(path.join(dir, "player-state.json"), JSON.stringify({
        schema_version: 1, mode: "original", state: "paused", speed: 2,
        source_first: recordedTime, source_last: recordedTime + 60,
        current_time: recordedTime + 5, updated_wall: Date.now() / 1000
      }));
      const port = await availablePort();
      const child = spawn(process.execPath, [serverEntry, "--host=127.0.0.1", `--port=${port}`,
        `--log-dir=${dir}`, `--state-dir=${path.join(dir, "state")}`], {
        cwd: path.resolve(__dirname, ".."), stdio: ["ignore", "ignore", "pipe"],
        env: { ...process.env, STM_CONFIG_FILE: "", STM_PLAYBACK_STATE_FILE: "", STM_PROCESS_CONTROL_SOCKET: brokerPath }
      });
      children.push(child);
      urls[name] = `http://127.0.0.1:${port}`;
      await waitFor(urls[name] + "/api/playback", child);
    }
    const recorded = await (await fetch(urls.recorded + "/api/runtime/processes")).json();
    assert.equal(recorded.control.available, false);
    assert.equal(connections, 0, "recorded viewing must not contact the live control broker");
    const live = await (await fetch(urls.live + "/api/runtime/processes")).json();
    assert.equal(live.control.available, true);
    assert.ok(connections > 0);
    const fileTimeline = await (await fetch(urls.recorded + "/api/timeline")).json();
    const liveTimeline = await (await fetch(urls.live + "/api/timeline")).json();
    assert.equal(fileTimeline.window.to, recordedTime + 5);
    assert.ok(Math.abs(liveTimeline.window.to - Date.now() / 1000) < 5);
  } finally {
    for (const child of children) {
      if (child.exitCode === null) { child.kill("SIGTERM"); await new Promise(resolve => child.once("exit", resolve)); }
    }
    if (broker.listening) await new Promise(resolve => broker.close(resolve));
    fs.rmSync(root, { recursive: true, force: true });
  }
});

