    config_file = Path(args.config).resolve()
    config = read_json(config_file)
    if not isinstance(config, dict):
        raise ValueError(f'invalid STM config: {config_file}')
    config = json.loads(json.dumps(config))
    refs = config.pop('configs', {})
    if config.get('stm'):
        raise ValueError('legacy stm config overlay is unsupported for jobs; use top-level input/logs/configs')
    config['configs'] = {}
    for field, aliases in {'tshark': ['tshark', 'tshark_config'], 'protocol_map': ['protocol_map'],
                           'alerts': ['alerts', 'alert_config']}.items():
        ref = next((refs[key] for key in aliases if refs.get(key)), None)
        if ref:
            source = Path(ref)
            if not source.is_absolute():
                source = config_file.parent / source
            data = read_json(source)
            if data is None:
                raise ValueError(f'invalid referenced config: {source}')
            destination = root / 'config' / f'{field}.json'
            atomic_json(destination, data)
            config['configs'][field] = destination.name
    if args.tshark:
        if 'tshark' in config['configs']:
            file = root / 'config' / config['configs']['tshark']
            data = read_json(file)
            data.get('tshark', data)['program'] = args.tshark
            atomic_json(file, data)
        else:
            config.setdefault('tshark', {})['program'] = args.tshark
    # FE's existing settings readers deliberately accept only local relative refs.
    # Keep their schema/catalog available without referring back to live config.
    for name in ('alerts_config.schema.json', 'protocol_map.schema.json', 'stm_config.schema.json',
                 'tshark_config.schema.json', 'capture_policy.schema.json', 'capture_policy.json'):
        source = config_file.parent / name
        if not source.is_file():
            source = PROJECT / 'conf' / name
        if source.is_file():
            shutil.copyfile(source, root / 'config' / name)
    config['logs'] = {'dir': str(root / 'result'), 'event_journal_dir': 'event-journal',
                      'metrics_journal_dir': 'metrics-journal', 'journal_retention_hours': 0}
    # Capture is descriptive only. No dumpcap, healthd, storage-manager or live broker runs.
    config.setdefault('capture', {})['output'] = str(root / 'capture' / 'cap.pcapng')
    config['capture']['ring_files'] = args.ring_files
