export async function prepareStateDirectory(directory: string) {
  let operation = "create_state_directory";
  const probe = path.join(directory, ".stm-write-check-" + randomUUID());
  let ownedProbe: string | undefined;
  try {
    await mkdir(directory, { recursive: true });
    operation = "check_state_directory_write";
    const handle = await open(probe, "wx", 0o600);
    ownedProbe = probe;
    try { await handle.writeFile("STM write check\n"); }
    finally { await handle.close(); }
    operation = "check_state_directory_rename";
    await rename(probe, probe + ".renamed");
    ownedProbe = probe + ".renamed";
    operation = "check_state_directory_cleanup";
    await unlink(ownedProbe);
    ownedProbe = undefined;
  } catch (error) {
    throw new OperationError(operation, { path: directory }, error);
  } finally {
    if (ownedProbe) await unlink(ownedProbe).catch(() => undefined);
  }
}
