export class OperationError extends Error {
  constructor(public operation: string, public context: Record<string, unknown>, public cause: unknown) {
    super(cause instanceof Error ? cause.message : String(cause));
  }
}

export function reportError(operation: string, error: unknown, context: Record<string, unknown> = {}) {
  let detail = error;
  const seen = new Set<unknown>();
  while (detail && typeof detail === "object" && !seen.has(detail)) {
    seen.add(detail);
    if (detail instanceof OperationError) {
      operation = detail.operation;
      context = { ...context, ...detail.context };
    }
