export class OperationError extends Error {
  constructor(public operation: string, public context: Record<string, unknown>, public cause: unknown) {
    super(cause instanceof Error ? cause.message : String(cause));
  }
}

export function reportError(operation: string, error: unknown, context: Record<string, unknown> = {}) {
  let detail = error;
  const seen = new Set<unknown>();
  while (detail && typeof detail === "object" && !seen.has(detail)) {
    seen.add(detail);
    if (detail instanceof OperationError) {
      operation = detail.operation;
      context = { ...context, ...detail.context };
    }
    const cause = (detail as { cause?: unknown }).cause;
    if (cause === undefined) break;
    detail = cause;
  }
  const native = detail as NodeJS.ErrnoException | undefined;
  console.error(JSON.stringify({
    time: new Date().toISOString(), level: "error", process: "frontend", pid: process.pid,
    operation, ...context,
    code: native?.code, syscall: native?.syscall, errorPath: native?.path,
    message: detail instanceof Error ? detail.message : String(detail),
    stack: detail instanceof Error ? detail.stack : undefined
  }));
}
