import { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import type { FlowListItem, InterfaceListItem, ProtocolDetail, StreamAlertSummary, StreamListItem } from "../types/api";
import { alertCountsForStreams, alertTargetsForStreams, visibleRecentAlert, type AlertCounts } from "./alertTargets";
import { Sparkline } from "./Sparkline";
import { Icon } from "./ui/Icon";
import { formatAbsoluteDateTime, formatBitrate, formatFlowEndpoints, formatRelativeTime } from "./format";
import { useI18n } from "../i18n";
import { dataNowSec } from "../dataClock";

export type StreamsViewMode = "tree" | "ranked";
export type StreamsRankTarget = "flows" | "streams";
export type StreamsSortOrder = "tree" | "bitrate-desc" | "bitrate-asc" | "alerts-desc" | "last-seen-desc";

type StreamTableProps = {
  streams: StreamListItem[];
  interfaces: InterfaceListItem[];
  selectedStreamKey: string | null;
  selectedFlowKey: string | null;
  selectedInterfaceKey: string | null;
  overviewMode?: boolean;
  expandLevel?: "interface" | "proto" | "stream" | "flow";
  viewMode?: StreamsViewMode;
  rankTarget?: StreamsRankTarget;
  sortOrder?: StreamsSortOrder;
  onSelectInterface: (interfaceKey: string) => void;
  onSelectStream: (streamKey: string) => void;
  onSelectFlow: (streamKey: string, flowKey: string) => void;
  onInspect?: (streamKey: string, flowKey?: string) => void;
  onInspectInterface?: (interfaceKey: string) => void;
  timeTravel?: boolean;
  pickerMode?: boolean;
  showAlerts?: boolean;
  recentAlertRetentionMin?: number;
  referenceTimeSec?: number;
  dismissedRecent?: ReadonlySet<string>;
  onClearRecent?: () => void;
};

const TOTAL_COLOR = "var(--chart-rx)";
const FLOW_ROLE_COLORS: Record<string, string> = {
  media: "var(--chart-flow-media)",
  fec_row: "var(--chart-flow-fec-row)",
  fec_col: "var(--chart-flow-fec-col)",
  control: "var(--chart-flow-control)",
  mixed: "var(--chart-flow-mixed)",
  default: "var(--chart-flow-default)"
};
const FLOW_ROLE_LINE_COLORS: Record<string, string> = {
  media: "var(--chart-flow-media-line)",
  fec_row: "var(--chart-flow-fec-row-line)",
  fec_col: "var(--chart-flow-fec-col-line)",
  control: "var(--chart-flow-control-line)",
  mixed: "var(--chart-flow-mixed-line)",
  default: "var(--chart-flow-default-line)"
};
const DONUT_COLORS = ["var(--chart-rx)", "var(--chart-flow-media)", "var(--chart-flow-fec-col)", "var(--chart-flow-fec-row)", "var(--chart-flow-mixed)", "var(--chart-flow-default)"];
const ENABLE_FLIP_ANIMATION = false;
const ENABLE_SPARKLINES = true;
const ENABLE_OVERVIEW_STATS = true;
const ENABLE_OVERVIEW_CHARTS = false;
const MAX_STREAM_ROWS_PER_GROUP = 200;
const MAX_FLOW_ROWS_PER_STREAM = 80;
const STREAM_TABLE_OVERSCAN_PX = 600;
const STREAM_TABLE_ROW_HEIGHT = { interface: 40, scope: 40, proto: 40, stream: 40, group: 40, flow: 40, truncated: 32 };

type InterfaceGroup = {
  key: string;
  name: string;
  interfaceItem?: InterfaceListItem;
  streams: StreamListItem[];
};

type ScopeGroup = { key: string; label: string; streams: StreamListItem[] };
type StreamDisplayGroup = { key: string; label: string; confidence?: "confirmed" | "heuristic"; streams: StreamListItem[]; grouped: boolean };

type FlatRow = { treeLevel?: number } & (
  | { key: string; type: "interface"; height: number; group: InterfaceGroup }
  | { key: string; type: "scope"; height: number; group: ScopeGroup }
  | { key: string; type: "proto"; height: number; group: { key: string; proto: string; streams: StreamListItem[] } }
  | { key: string; type: "group"; height: number; group: StreamDisplayGroup }
  | { key: string; type: "stream"; height: number; stream: StreamListItem }
  | { key: string; type: "flow"; height: number; stream: StreamListItem; flow: FlowListItem }
  | { key: string; type: "truncated"; height: number; label: string; depth: "stream" | "flow" }
);


type TreeGuideData = {
  depth: number;
  ancestorDepths: number[];
  hasPreviousSibling: boolean;
  hasNextSibling: boolean;
};

type StickyContextItem = {
  kind: "interface" | "scope" | "proto" | "group" | "stream";
  label: string;
  proto?: string;
  title?: string;
};

type GuidedFlatRow = FlatRow & { treeGuide: TreeGuideData };

type SelectionAncestor = { rowKey: string; key: string; kind: "interface" | "scope" | "proto" | "stream" };

function treeDepth(row: FlatRow) {
  if (row.treeLevel !== undefined) return row.treeLevel;
  switch (row.type) {
    case "interface": return 0;
    case "scope": return 1;
    case "proto": return 2;
    case "group": return 3;
    case "stream": return 4;
    case "flow": return 5;
    case "truncated": return row.depth === "stream" ? 4 : 5;
  }
}

function withTreeGuides(rows: FlatRow[]): GuidedFlatRow[] {
  const depths = rows.map(treeDepth);
  const nextSibling = rows.map((_, index) => {
    const depth = depths[index];
    for (let next = index + 1; next < rows.length; next += 1) {
      if (depths[next] < depth) return false;
      if (depths[next] === depth) return true;
    }
    return false;
  });
  const ancestry: Array<{ key: string; depth: number; hasNextSibling: boolean } | undefined> = [];
  const seenSiblings = new Set<string>();

  return rows.map((row, index) => {
    const depth = depths[index];
    ancestry.length = depth;
    const parentKey = ancestry.slice(0, depth).filter(Boolean).map((item) => item!.key).join("/") || "root";
    const siblingKey = `${parentKey}:${depth}`;
    const hasPreviousSibling = seenSiblings.has(siblingKey);
    seenSiblings.add(siblingKey);
    const guide = {
      depth,
      ancestorDepths: ancestry.slice(0, depth)
        .filter((item) => item?.hasNextSibling)
        .map((item) => item!.depth),
      hasPreviousSibling,
      hasNextSibling: nextSibling[index]
    };
    ancestry[depth] = { key: row.key, depth, hasNextSibling: nextSibling[index] };
    return { ...row, treeGuide: guide };
  });
}

function TreeGuideLines({ guide }: { guide: TreeGuideData }) {
  const ownSegments = [
    guide.hasPreviousSibling ? "incoming" : "",
    guide.hasNextSibling ? "outgoing" : ""
  ].filter(Boolean);
  return <span className="tree-guide-layer" aria-hidden="true">
    {guide.ancestorDepths.map((depth) => <span key={`ancestor-${depth}`} className={`tree-guide-line tree-guide-depth-${depth}`} />)}
    {ownSegments.map((segment) => <span key={segment} className={`tree-guide-line tree-guide-depth-${guide.depth} tree-guide-${segment}`} />)}
  </span>;
}
  };

  const renderScopeRow = (scopeGroup: ScopeGroup, rowKey = `scope:${scopeGroup.key}`) => {
    const opened = expandedScopeGroups.has(scopeGroup.key);
    const active = scopeGroup.streams.some((stream) => stream.active);
    const bitrate = scopeGroup.streams.reduce((sum, stream) => sum + streamBitrateOf(stream), 0);
    const sparkline = sumSparklines(scopeGroup.streams.map((stream) => stream.sparkline));
    return (
      <div className="scope-tree">
        <div className="scope-row">
          <button type="button" className={`tree-toggle expandable ${opened ? "open" : ""}`} aria-label={`${opened ? "Collapse" : "Expand"} ${scopeGroup.label}`} onClick={() => toggleScopeGroup(scopeGroup.key)}><Icon name="expand" size={15} /></button>
          <span className={`proto-status ${active ? "active" : "stale"}`} />
          <span className="proto-main"><span className="proto-title"><strong>{scopeGroup.label}</strong><DescendantCountBadge count={scopeGroup.streams.length} /><AlertCountBadge counts={groupAlertCounts(scopeGroup.streams)} />{renderHiddenSelectionBadge(rowKey)}</span></span>
          <span className="stream-traffic-block"><span className="stream-rate">{formatBitrate(bitrate)}</span></span>
          {ENABLE_SPARKLINES && <span className="stream-trend-block"><Sparkline stretch values={sparkline} width={150} height={24} color="var(--chart-sparkline)" strokeWidth={1.1} /></span>}
        </div>
      </div>
    );
  };

  const renderProtoRow = (protoGroup: { key: string; proto: string; streams: StreamListItem[] }) => {
    const opened = expandedProtoGroups.has(protoGroup.key);
    const active = protoGroup.streams.some((stream) => stream.active);
    const bitrate = protoGroup.streams.reduce((sum, stream) => sum + streamBitrateOf(stream), 0);
    const sparkline = sumSparklines(protoGroup.streams.map((stream) => stream.sparkline));
    return (
      <div className="proto-tree proto-tree-virtual" data-flip-key={`proto:${protoGroup.key}`}>
        <div className="proto-row">
          <button type="button" className={`tree-toggle expandable ${opened ? "open" : ""}`} aria-label={`${opened ? "Collapse" : "Expand"} ${protoGroup.proto}`} onClick={() => toggleProtoGroup(protoGroup.key)}><Icon name="expand" size={15} /></button>
          <span className={`proto-status ${active ? "active" : "stale"}`} />
          <span className="proto-main">
            <span className="proto-title">
              <strong>{protoGroup.proto}</strong>
              <DescendantCountBadge count={protoGroup.streams.length} /><AlertCountBadge counts={groupAlertCounts(protoGroup.streams)} />
              {renderHiddenSelectionBadge(`proto:${protoGroup.key}`)}
            </span>
          </span>
          <span className="stream-traffic-block"><span className="stream-rate">{formatBitrate(bitrate)}</span></span>
          {ENABLE_SPARKLINES && <span className="stream-trend-block"><Sparkline stretch values={sparkline} width={150} height={24} color="var(--chart-sparkline)" strokeWidth={1.1} /></span>}
        </div>
      </div>
    );
  };

  const renderInterfaceRow = (group: InterfaceGroup) => {
    const opened = expandedInterfaces.has(group.key);
    const interfaceKey = group.interfaceItem?.key;
    return (
      <div className="interface-tree interface-tree-virtual" data-flip-key={`interface:${group.key}`}>
        <div
          className={`interface-row ${group.interfaceItem?.key === selectedInterfaceKey ? "selected" : ""}`}
          role={group.interfaceItem ? "button" : undefined}
          tabIndex={group.interfaceItem ? 0 : undefined}
          onClick={() => { if (group.interfaceItem) onSelectInterface(group.interfaceItem.key); }}
          onKeyDown={(event) => {
            if (!group.interfaceItem || event.target !== event.currentTarget || (event.key !== "Enter" && event.key !== " ")) return;
            event.preventDefault();
            onSelectInterface(group.interfaceItem.key);
          }}
        >
          <button type="button" className={`tree-toggle expandable ${opened ? "open" : ""}`} aria-label={`${opened ? "Collapse" : "Expand"} ${group.name}`} onClick={(event) => { event.stopPropagation(); toggleInterface(group.key); }}><Icon name="expand" size={15} /></button>
          <span className={`interface-status ${group.interfaceItem?.available !== false ? "active" : "stale"}`} />
          <span className="interface-main">
            <span className="interface-title"><strong>{group.name}</strong><span className="interface-link-summary">{formatLinkSummary(group.interfaceItem)}</span><DescendantCountBadge count={group.streams.length} /><AlertCountBadge counts={groupAlertCounts(group.streams)} />{renderHiddenSelectionBadge(`interface:${group.key}`)}</span>
          </span>
          {ENABLE_OVERVIEW_CHARTS && <InterfaceHeadroomGauge item={group.interfaceItem} />}
          <span className="interface-sparklines">
            <span className="interface-rate-row">
              <span className="interface-rate-label">RX</span>
              <span className="interface-rate-value">{formatBitrate(interfaceBitrateOf(group.interfaceItem, "rx"))}</span>
              {ENABLE_SPARKLINES && <Sparkline stretch values={group.interfaceItem?.rxSparkline ?? []} width={150} height={18} color="var(--chart-rx)" strokeWidth={1.1} />}
            </span>
            <span className="interface-rate-row">
              <span className="interface-rate-label">TX</span>
              <span className="interface-rate-value">{formatBitrate(interfaceBitrateOf(group.interfaceItem, "tx"))}</span>
              {ENABLE_SPARKLINES && <Sparkline stretch values={group.interfaceItem?.txSparkline ?? []} width={150} height={18} color="var(--chart-tx)" strokeWidth={1.1} />}
            </span>
          </span>
          {!pickerMode && interfaceKey && <RowInspectButton onInspect={onInspectInterface ? () => onInspectInterface(interfaceKey) : undefined} />}
        </div>
      </div>
    );
  };

  const renderTruncatedRow = (row: Extract<FlatRow, { type: "truncated" }>) => {
    const className = row.depth === "flow" ? "flow-list-row flow-list-row-truncated stream-table-virtual-flow" : "stream-row stream-row-truncated stream-table-virtual-stream";
    return (
      <div className={className}>
        <span className="flow-main stream-main">
          <span className="flow-subtitle stream-subtitle">{row.label}</span>
        </span>
      </div>
    );
  };

  return (
    <div
      ref={tableRef}
      className={`stream-table ${overviewMode ? "overview-mode" : ""} ${pickerMode ? "picker-mode" : ""}`}
      onScroll={() => {
        scrollingRef.current = true;
        if (scrollRafRef.current === null) {
          scrollRafRef.current = window.requestAnimationFrame(() => {
            scrollRafRef.current = null;
            const root = tableRef.current;
            if (!root) return;
            setViewport((current) => {
              const next = { top: root.scrollTop, height: root.clientHeight || 640 };
    : [{ streams, key: "root" }];
  return collections.flatMap((collection) =>
    buildScopeGroups(collection.streams, collection.key).flatMap((scopeGroup) =>
      buildProtoGroups(scopeGroup.streams, scopeGroup.key).map((protoGroup) => protoGroup.key)
    )
