export function useAnalysisSource() {
  const [presentation, setPresentation] = useState(() => getAnalysisSource().presentation());
  useEffect(() => {
    let cancelled = false;
    const update = () => {
      const source = getAnalysisSource();
      void source.refresh().then(() => {
        if (!cancelled) setPresentation(source.presentation());
      }).catch(() => undefined);
    };
    update();
    const timer = window.setInterval(update, 1000);
    return () => { cancelled = true; window.clearInterval(timer); };
  }, []);
