function formatPercent(value: number | undefined) {
  if (value === undefined || !Number.isFinite(value)) return "-";
  return `${Math.round(Math.max(0, Math.min(1, value)) * 100)}%`;
}

function formatLinkSummary(item: InterfaceListItem | undefined) {
  if (!item?.link) return "link unknown";
  const speed = item.link.speedMbps ? formatLinkSpeed(item.link.speedMbps) : "speed unknown";
  const duplex = item.link.duplex ? ` ${item.link.duplex}` : "";
  const state = item.link.operstate ? ` ${item.link.operstate}` : "";
  return `${speed}${duplex}${state}`;
}

function formatLinkSpeed(speedMbps: number) {
  if (speedMbps < 1000) return `${speedMbps}M`;
  const gbps = speedMbps / 1000;
  return `${Number.isInteger(gbps) ? gbps.toFixed(0) : gbps.toFixed(1)}G`;
}

