import type { AnalysisSource, SourcePresentation } from "../analysisSource";
import type { WsMessage } from "../types/api";
import { getFileAnalysisStatus } from "../api/client";
import { createFileAnalysisSource } from "./fileAnalysisSource";
import { createPlaybackSource } from "./playbackSource";

// Keep discovery retryable when the first request fails. Concrete adapters do
// not depend on one another, and an unknown source never adopts a live clock.
export function createAnalysisSource(): AnalysisSource {
  let selected: AnalysisSource | null = null;
  return {
    nowSec: () => selected?.nowSec() ?? 0,
    presentation: (): SourcePresentation => selected?.presentation() ?? { advancing: false, badge: null },
    async refresh(timeoutMs) {
      if (!selected) {
        const status = await getFileAnalysisStatus(timeoutMs);
        selected = status ? createFileAnalysisSource(getFileAnalysisStatus) : createPlaybackSource();
        if (status) { selected.handleMessage({ type: "analysis:status", analysis: status }); return; }
      }
      await selected.refresh(timeoutMs);
    },
    handleMessage(message: WsMessage) {
      if (!selected && message.type === "analysis:status") selected = createFileAnalysisSource(getFileAnalysisStatus);
      if (!selected && message.type === "playback:status") selected = createPlaybackSource();
      return selected?.handleMessage(message) ?? false;
    }
  };
}
