function buildInterfaceGroups(interfaces: InterfaceListItem[], streams: StreamListItem[], order: StreamsSortOrder = "tree") {
  const interfaceById = new Map(interfaces.filter((item) => item.interfaceId !== undefined).map((item) => [item.interfaceId!, item]));
  const groups = new Map<string, { key: string; name: string; interfaceItem?: InterfaceListItem; streams: StreamListItem[] }>();

  for (const item of interfaces) {
    groups.set(item.key, {
      key: item.key,
      name: item.name,
      interfaceItem: item,
      streams: []
    });
  }

  for (const stream of streams) {
    const item = stream.interfaceId !== undefined ? interfaceById.get(stream.interfaceId) : undefined;
    const key = item ? item.key : stream.interfaceName ? `name:${stream.interfaceName}` : "unknown";
    const name = item?.name ?? stream.interfaceName ?? "Unknown interface";
    const group = groups.get(key) ?? { key, name, interfaceItem: item, streams: [] };
    group.streams.push(stream);
    groups.set(key, group);
  }

  return [...groups.values()]
    .filter((group) => group.streams.length > 0 || group.interfaceItem)
    .sort((a, b) => {
      if (order !== "tree") return compareStreamGroups(a, b, order, (group) => group.name);
      if (a.key === "unknown") return 1;
      if (b.key === "unknown") return -1;
      return (a.interfaceItem?.interfaceId ?? Number.MAX_SAFE_INTEGER) - (b.interfaceItem?.interfaceId ?? Number.MAX_SAFE_INTEGER) || a.name.localeCompare(b.name);
    });
}

