export function Sparkline({ values, width = 120, height = 30, minValue, maxValue, color, strokeWidth = 2, stretch = false }: SparklineProps) {
  const gradientId = "sparkline-fill-" + useId().replaceAll(":", "");
  if (values.length === 0) return <div className="sparkline-empty" style={{ width, height }} />;

  const min = minValue ?? Math.min(...values);
  const max = maxValue ?? Math.max(...values);
  const range = max - min || 1;
  const baseline = height - 2;
  const coordinates = values.map((value, index) => {
    const clamped = Math.max(min, Math.min(max, value));
    return {
      x: values.length === 1 ? width : (index / (values.length - 1)) * width,
      y: height - ((clamped - min) / range) * (height - 4) - 2
    };
  });
  const points = coordinates.map(({ x, y }) => `${x.toFixed(1)},${y.toFixed(1)}`).join(" ");
  const first = coordinates[0];
  const last = coordinates[coordinates.length - 1];
  const areaPath = `M ${first.x.toFixed(1)},${baseline.toFixed(1)} L ${points} L ${last.x.toFixed(1)},${baseline.toFixed(1)} Z`;

  return (
    <svg className="sparkline" width={width} height={height} viewBox={`0 0 ${width} ${height}`} preserveAspectRatio={stretch ? "none" : undefined} style={color ? { color } : undefined}>
      <defs>
        <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor="currentColor" stopOpacity="0.20" />
          <stop offset="100%" stopColor="currentColor" stopOpacity="0.02" />
        </linearGradient>
      </defs>
      <path d={areaPath} fill={`url(#${gradientId})`} />
      <polyline points={points} fill="none" stroke="currentColor" strokeWidth={strokeWidth} vectorEffect={stretch ? "non-scaling-stroke" : undefined} strokeLinejoin="round" strokeLinecap="round" />
    </svg>
  );
}
