        atomic_json(root / 'analysis-state.json', initial_state(manifest))
        return manifest
    except BaseException as exc:
        interrupted = isinstance(exc, KeyboardInterrupt)
        detail = str(exc).strip() or repr(exc)
        error = f'preparation interrupted (KeyboardInterrupt)' if interrupted else f'{type(exc).__name__}: {detail}'
        try:
            log = root / 'runtime' / 'preparation-error.log'
            log.parent.mkdir(exist_ok=True)
            log.write_text(traceback.format_exc())
        except OSError:
            pass  # Keep the original error if even the diagnostic cannot be written.
        atomic_json(root / 'analysis-state.json', {'enabled': True, 'schema_version': 1,
                    'kind': 'file', 'phase': 'preparation',
                    'state': 'interrupted' if interrupted else 'failed',
                    'error': error, 'errorType': type(exc).__name__})
        raise


def packet_times(path):
    clocks = []
    for kind, block in blocks(path):
    for name in ('event', 'metrics'):
        directory = root / 'result' / f'{name}-journal'
        files = list(directory.rglob('*.ndjson'))
        def order(file):
            match = re.fullmatch(r'(\d{2})(?:\.part(\d+))?\.ndjson', file.name)
            return str(file.parent), match[1] if match else file.name, int(match[2] or 0) if match else 0
        files.sort(key=order)
        result[f'{name}_cursor'] = None if not files else {
            'path': str(files[-1].relative_to(directory)), 'offset': files[-1].stat().st_size}
    return result


def projection_ready(root):
    cursor = read_json(root / 'result' / 'derived' / 'projector-state.json')
    if not isinstance(cursor, dict) or cursor.get('schema_version') != 1:
        return False
    tail = journal_tail(root)
    for key, value in tail.items():
        position = cursor.get(key)
        if not isinstance(position, dict):
            return False
        if value is None:
            if position.get('path') != '' or position.get('offset') != 0:
                return False
        elif any(position.get(field) != expected for field, expected in value.items()):
            return False
    return cursor.get('pending_topology', {}).get('dirty') is False



def supervisor_env(root, job):
    env = {**os.environ, 'STM_ANALYSIS_ROOT': str(root), 'STM_ANALYSIS_SCRIPT': job['script'],
           'STM_ANALYSIS_PYTHON': job['python'], 'STM_ANALYSIS_BIN': job['binDir'],
           'STM_ANALYSIS_FE': job['feDir'], 'STM_ANALYSIS_NODE': job['node'],
           'STM_ANALYSIS_HOST': job['host'], 'STM_ANALYSIS_PORT': str(job['port'])}
    # Inherited live FE path overrides must not bypass the job's data root.
    for key in ('DERIVED_DIR', 'EVENT_JOURNAL_DIR', 'STREAM_STATE_DIR', 'METRICS_SAMPLES_1S_DIR',
                'METRICS_SAMPLES_1M_DIR', 'TIMELINE_EVENTS_DIR', 'TIMELINE_CHECKPOINT_DIR',
                'TIMELINE_AVAILABILITY_DIR', 'TOPOLOGY_CHECKPOINT_DIR', 'TOPOLOGY_UPDATES_DIR',
                'TIMELINE_LIVE_FILE', 'TOPOLOGY_LIVE_FILE', 'CAPTURE_HEALTH_LIVE_FILE',
                'CAPTURE_HEALTH_EVENTS_FILE', 'STM_PLAYBACK_STATE_FILE', 'STM_ANALYSIS_STATE_FILE',
                'INSPECTOR_METRIC_SCHEMA_FILE', 'STM_CAPTURE_POLICY_FILE'):
        env.pop(key, None)
    env['STM_LOG_LEVEL_FILE'] = str(root / 'runtime' / 'log-levels.json')
    for key in [key for key in env if key.startswith('STM_ANALYSIS_')]:
        if not re.fullmatch(r'[A-Za-z0-9_./:-]+', env[key]):
            raise ValueError(f'{key}: Supervisor values must not contain spaces or special characters')
    return env


def ctl(root, job, *command, check=True):
    return subprocess.run(['supervisorctl', '-c', str(PROJECT / 'docker' / 'supervisord.analysis.conf'),
                           *command], env=supervisor_env(root, job), capture_output=True, text=True,
                           check=check, timeout=50)


def services(root, action):
    job = read_json(root / 'job.json')
    if not job:
        state = read_json(root / 'analysis-state.json')
        runtime_exists = any((root / 'runtime' / name).exists() for name in ('supervisor.sock', 'supervisord.pid'))
        if action == 'status' and state:
            print(json.dumps(state, indent=2))
            print('preparation has not completed; Supervisor startup is unconfirmed' if runtime_exists else
                  'preparation has not completed; Supervisor and FE have not started')
            return
        if action in ('stop', 'shutdown') and state and not runtime_exists:
            if state.get('state') == 'preparing':
                raise ValueError('preparation is still running; cancel the original up/prepare command with Ctrl+C')
            if state.get('state') in ('failed', 'interrupted'):
                print('Supervisor and FE were not started; there are no analysis services to stop')
                return
        raise ValueError('job.json is missing; prepare the job first')
    if action == 'up':
        if read_json(root / 'analysis-state.json', {}).get('state') != 'ready':
            raise ValueError('job must be ready; use a new output to rerun')
        for file in (Path(job['binDir']) / 'stm', Path(job['binDir']) / 'stm_projector',
                     Path(job['feDir']) / 'server' / 'dist' / 'index.js',
                     Path(job['feDir']) / 'client' / 'dist' / 'index.html'):
            if not file.is_file():
                raise ValueError(f'build required: {file}')
        if len(str(root / 'runtime' / 'supervisor.sock').encode()) > 100:
            raise ValueError('output path too long for Supervisor Unix socket')
        if (root / 'runtime' / 'supervisor.sock').exists() or (root / 'runtime' / 'supervisord.pid').exists():
            raise ValueError('Supervisor runtime already exists; inspect status/shutdown first')
        subprocess.run(['supervisord', '-c', str(PROJECT / 'docker' / 'supervisord.analysis.conf')],
                       env=supervisor_env(root, job), check=True)
        try:
            for name in ('projector', 'frontend', 'analysis'):
                result = ctl(root, job, 'start', name)
                print(result.stdout.strip())
                if name == 'frontend':
                    host = {'0.0.0.0': '127.0.0.1', '::': '::1'}.get(job['host'], job['host'])
                    host = f'[{host}]' if ':' in host else host
                    url = f'http://{host}:{job["port"]}/api/analysis'
                    opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))
                    deadline = time.monotonic() + 15
                    while True:
                        try:
                            with opener.open(url, timeout=1) as response:
                                if response.status == 200:
                                    break
                        except (OSError, urllib.error.URLError):
                            pass
                        if time.monotonic() >= deadline:
                            raise TimeoutError(f'FE readiness timed out; see {root / "runtime/frontend.log"}')
                        time.sleep(.1)
        except Exception:
            try:
                services(root, 'shutdown')
            except Exception as cleanup:
                print(f'analysis service cleanup failed: {cleanup}', file=sys.stderr)
            raise
        print(f'http://{job["host"]}:{job["port"]} (analysis EOF leaves projector and FE running)')
    elif action == 'stop':
        result = ctl(root, job, 'stop', 'analysis', check=False)
        if result.returncode not in (0, 1) or (result.returncode and 'not running' not in result.stdout):
            raise RuntimeError(result.stdout + result.stderr)
    elif action == 'shutdown':
        ctl(root, job, 'stop', 'all')
        ctl(root, job, 'shutdown')
        deadline = time.monotonic() + 15
        while (root / 'runtime' / 'supervisor.sock').exists() or (root / 'runtime' / 'supervisord.pid').exists():
            if time.monotonic() > deadline:
                raise TimeoutError('Supervisor shutdown timed out')
            time.sleep(.1)
    else:
        state = read_json(root / 'analysis-state.json')
        if state:
            state['projection'] = 'ready' if state.get('state') in TERMINAL and projection_ready(root) else 'pending'
        print(json.dumps(state, indent=2))
        if (root / 'runtime' / 'supervisor.sock').exists():
            print(ctl(root, job, 'status', check=False).stdout)


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('action', metavar='{prepare,run,up,status,stop,shutdown}', choices=['prepare', 'run', 'up', 'status', 'stop', 'shutdown', '_work', '_produce'])
    parser.add_argument('--output', required=True)
    parser.add_argument('--source')
    parser.add_argument('--config', default=str(PROJECT / 'conf' / 'stm_config.json'))
    parser.add_argument('--from', dest='start', type=timestamp)
    parser.add_argument('--to', type=timestamp)
    parser.add_argument('--duration', type=duration)
    parser.add_argument('--pre-roll', type=float, default=0, help='tshark reassembly pre-roll in recorded seconds')
    parser.add_argument('--pace', choices=['full', 'recorded'], default='full')
    parser.add_argument('--speed', type=positive, default=1)
    parser.add_argument('--ring-files', type=int, default=60)
    parser.add_argument('--gap-threshold', type=positive, default=2)
    parser.add_argument('--drain-timeout', type=positive, default=120)
    parser.add_argument('--bin-dir', default=os.environ.get('STM_BIN_DIR', str(PROJECT / 'be' / 'build')))
    parser.add_argument('--fe-dir', default=os.environ.get('STM_FE_DIR', str(PROJECT / 'fe')))
    parser.add_argument('--node', default=os.environ.get('STM_NODE_BIN', 'node'))
    parser.add_argument('--tshark', help='override tshark executable in the job config snapshot')
    parser.add_argument('--host', default='127.0.0.1')
    parser.add_argument('--port', type=int, default=3200)
    arguments = sys.argv[1:] if argv is None else argv
    args = parser.parse_args(arguments)
    try:
        root = safe_root(args.output)
        if not 1 <= args.port <= 65535:
            raise ValueError('port must be 1..65535')
        if args.action in ('run', 'up') and not args.source:
            options = {'--config', '--from', '--to', '--duration', '--pre-roll', '--pace', '--speed',
                       '--ring-files', '--gap-threshold', '--drain-timeout', '--bin-dir', '--fe-dir',
                       '--node', '--tshark', '--host', '--port'}
            if any(token.split('=', 1)[0] in options for token in arguments):
                raise ValueError('prepared job settings are fixed; specify options with --source on a new output')
        if args.action in ('prepare', 'run', 'up') and args.source:
            prepare(args, root)
        elif args.action == 'prepare':
            raise ValueError('--source is required for prepare')
        if args.action == 'prepare':
            print(f'prepared: {root / "manifest.json"}')
            return 0
        if args.action in ('run', '_work'):
            return work(root)
        if args.action == '_produce':
            return produce(root)
        services(root, args.action)
        return 0
    except KeyboardInterrupt:
        print('file analysis: interrupted (KeyboardInterrupt)', file=sys.stderr)
        return 130
    except (OSError, ValueError, RuntimeError, subprocess.SubprocessError) as exc:
        print(f'file analysis: {str(exc).strip() or repr(exc)}', file=sys.stderr)
        return 1


if __name__ == '__main__':
    sys.exit(main())

