class CaptureIndex:
    """A disposable, versioned cache. File identity is checked by the caller."""
    def __init__(self, source, root, args, warnings):
        self.connection = None
        self.warnings = warnings
        self.summary = {'enabled': False, 'path': None, 'hits': 0, 'misses': 0}
        if getattr(args, 'no_index', False):
            return
        directory = Path(getattr(args, 'index_dir', None) or root.parent / '.stm-pcap-index').expanduser().resolve()
        key = hashlib.sha256(str(source).encode()).hexdigest()
        path = directory / f'{key}.sqlite3'
        if not disjoint(path, source) or not disjoint(path, root):
            raise ValueError('index must be outside source and output')
        self.summary['path'] = str(path)
        try:
            directory.mkdir(parents=True, exist_ok=True)
            self.connection = sqlite3.connect(path, timeout=.2)
            self.connection.execute('PRAGMA journal_mode=WAL')
            self.connection.execute('PRAGMA synchronous=NORMAL')
            self.connection.execute('CREATE TABLE IF NOT EXISTS captures_v1 ('
                'path TEXT, validation TEXT, fingerprint TEXT, metadata TEXT, PRIMARY KEY(path, validation))')
            self.connection.commit()
            self.summary['enabled'] = True
        except (OSError, sqlite3.Error) as exc:
            self.disable(exc)

    def disable(self, error):
        message = f'capture index unavailable; using normal inspection: {error}'
        self.warnings.append(message)
        print(f'file analysis: warning: {message}', file=sys.stderr, flush=True)
        self.close()
        self.summary['enabled'] = False

    def get(self, path, validation, identity):
        if self.connection is not None:
            try:
                row = self.connection.execute('SELECT fingerprint, metadata FROM captures_v1 WHERE path=? AND validation=?',
                                              (str(path), validation)).fetchone()
                if row is not None and json.loads(row[0]) == identity:
                    info = json.loads(row[1])
                    if self.valid(info, validation, identity[2]):
                        self.summary['hits'] += 1
                        return info
            except (ValueError, TypeError, sqlite3.Error) as exc:
                self.disable(exc)
        self.summary['misses'] += 1
        return None

    @staticmethod
    def valid(info, validation, size):
        if not isinstance(info, dict) or info.get('size') != size:
            return False
        count = info.get('packets')
        if not isinstance(count, int) or count < 0:
            return False
        first, last = info.get('first'), info.get('last')
        if count == 0:
